            dt.Columns.Add("Nome");
            dt.Columns.Add("valida");
            dt.Columns.Add("Modulo");
            dt.Columns.Add("Url");

            try
            {
                conn.Open();
                IDataReader dr = cmd.ExecuteReader();
                while (dr.Read())
                {
                    DataRow udr = dt.NewRow();
                    udr["moduloId"] = dr["ModuloId"];
                    udr["Nome"]          = dr["nome"];
                    udr["valida"] = dr["valida"];
                    udr["Modulo"] = dr["Modulo"];
                    udr["Url"] = dr["Url"];
