using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class AplicacaosController : Controller
    {
        private readonly CmsxDbContext _context;
        public AplicacaosController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        [HttpGet]
        public IEnumerable<Aplicacao> Get()
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (acessoTotal)
                return _context.Aplicacaos.OrderBy(a => a.Nome).ToArray();

            return _context.Aplicacaos
                .Where(a => a.Aplicacaoid.ToString() == claimAppId)
                .ToArray();
        }

        [HttpGet("{id}")]
        public IActionResult Get(string id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Aplicacaos.Find(Guid.TryParse(id, out var ig1) ? ig1 : (Guid?)null);
            if (item == null) return NotFound();
            if (!acessoTotal && item.Aplicacaoid.ToString() != claimAppId) return Forbid();
            return Ok(item);
        }

        public class NovaAplicacaoDto
        {
            public string? Nome { get; set; }
            public string? Url { get; set; }
            public string? Mailuser { get; set; }
            public string? Mailpassword { get; set; }
            public string? Mailserver { get; set; }
            public int? Mailport { get; set; }
            public bool? Issecure { get; set; }
            public string? Pagsegurotoken { get; set; }
            public string? Layoutchoose { get; set; }
            public string? Ogleadsense { get; set; }
            public string? Header { get; set; }
            public string? Pagefacebook { get; set; }
            public string? Pageinstagram { get; set; }
            public string? Pagetwitter { get; set; }
            public string? Pagelinkedin { get; set; }
            public string? Pagepinterest { get; set; }
            public string? Pageflicker { get; set; }
            public string? Idusuarioinicio { get; set; }
            public string? Telefone { get; set; }
            public string? Endereco { get; set; }
            public string? Descricao { get; set; }
        }

        // Criação de aplicação: somente admin
        [HttpPost]
        public IActionResult Post([FromBody] NovaAplicacaoDto dto)
        {
            var (acessoTotal, _) = UserContext();
            if (!acessoTotal) return Forbid();

            var item = new Aplicacao
            {
                Aplicacaoid     = Guid.NewGuid().ToString(),
                Nome            = dto.Nome,
                Url             = dto.Url,
                Mailuser        = dto.Mailuser,
                Mailpassword    = dto.Mailpassword,
                Mailserver      = dto.Mailserver,
                Mailport        = dto.Mailport,
                Issecure        = dto.Issecure.HasValue ? (byte?)(dto.Issecure.Value ? 1 : 0) : null,
                Pagsegurotoken  = dto.Pagsegurotoken,
                Layoutchoose    = string.IsNullOrWhiteSpace(dto.Layoutchoose) ? "_Layout.cshtml" : dto.Layoutchoose,
                Ogleadsense     = dto.Ogleadsense,
                Header          = dto.Header,
                Pagefacebook    = dto.Pagefacebook,
                Pageinstagram   = dto.Pageinstagram,
                Pagetwitter     = dto.Pagetwitter,
                Pagelinkedin    = dto.Pagelinkedin,
                Pagepinterest   = dto.Pagepinterest,
                Pageflicker     = dto.Pageflicker,
                Idusuarioinicio = dto.Idusuarioinicio,
                Datainicio      = DateTime.Now,
                Isactive        = true,
                Telefone        = dto.Telefone,
                Endereco        = dto.Endereco,
                Descricao       = dto.Descricao
            };
            _context.Aplicacaos.Add(item);

            // Auto-cria área Home com template padrão (se existir)
            var templatePadrao = _context.LayoutTemplates
                .FirstOrDefault(t => t.Tipo == "home" && t.Padrao);

            _context.Areas.Add(new Area
            {
                Areaid       = Guid.NewGuid().ToString(),
                Aplicacaoid  = item.Aplicacaoid.ToString(),
                Nome         = "Home",
                Url          = "home",
                Posicao      = 1,
                Layout       = templatePadrao?.Layout ?? "{\"blocos\":[]}"
            });

            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] NovaAplicacaoDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Aplicacaos.Find(Guid.TryParse(id, out var ig2) ? ig2 : (Guid?)null);
            if (item == null) return NotFound();
            if (!acessoTotal && item.Aplicacaoid.ToString() != claimAppId) return Forbid();

            item.Nome           = dto.Nome;
            item.Url            = dto.Url;
            item.Mailuser       = dto.Mailuser;
            item.Mailpassword   = dto.Mailpassword;
            item.Mailserver     = dto.Mailserver;
            item.Mailport       = dto.Mailport;
            item.Issecure       = dto.Issecure.HasValue ? (byte?)(dto.Issecure.Value ? 1 : 0) : null;
            item.Pagsegurotoken = dto.Pagsegurotoken;
            item.Layoutchoose   = string.IsNullOrWhiteSpace(dto.Layoutchoose) ? "_Layout.cshtml" : dto.Layoutchoose;
            item.Ogleadsense    = dto.Ogleadsense;
            item.Header         = dto.Header;
            item.Pagefacebook   = dto.Pagefacebook;
            item.Pageinstagram  = dto.Pageinstagram;
            item.Pagetwitter    = dto.Pagetwitter;
            item.Pagelinkedin   = dto.Pagelinkedin;
            item.Pagepinterest  = dto.Pagepinterest;
            item.Pageflicker    = dto.Pageflicker;
            item.Telefone       = dto.Telefone;
            item.Endereco       = dto.Endereco;
            item.Descricao      = dto.Descricao;
            _context.SaveChanges();
            return Ok(item);
        }

        // Ativação/desativação: somente admin
        [HttpPatch("{id}/status")]
        public IActionResult PatchStatus(string id, [FromBody] bool ativo)
        {
            var (acessoTotal, _) = UserContext();
            if (!acessoTotal) return Forbid();

            var item = _context.Aplicacaos.Find(Guid.TryParse(id, out var ig3) ? ig3 : (Guid?)null);
            if (item == null) return NotFound();
            item.Isactive  = ativo;
            item.Datafinal = ativo ? null : DateTime.Now;
            _context.SaveChanges();
            return Ok(item);
        }

        // Exclusão: somente admin
        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            var (acessoTotal, _) = UserContext();
            if (!acessoTotal) return Forbid();

            var item = _context.Aplicacaos.Find(Guid.TryParse(id, out var ig4) ? ig4 : (Guid?)null);
            if (item == null) return NotFound();
            _context.Aplicacaos.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class AreasController : Controller
    {
        private readonly CmsxDbContext _context;
        public AreasController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        [HttpGet]
        public IEnumerable<Area> Get([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var q = _context.Areas.AsQueryable();
            if (acessoTotal)
            {
                if (!string.IsNullOrEmpty(aplicacaoid))
                    q = q.Where(a => a.Aplicacaoid == aplicacaoid);
            }
            else
            {
                q = q.Where(a => a.Aplicacaoid == claimAppId);
            }
            return q.OrderBy(a => a.Posicao).ToArray();
        }

        public class NovaAreaDto
        {
            public string? Nome { get; set; }
            public string? Url { get; set; }
            public string? Descricao { get; set; }
            public string? Areaidpai { get; set; }
            public int? Posicao { get; set; }
            public int? Tipoarea { get; set; }
            public string? Aplicacaoid { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] NovaAreaDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = new Area
            {
                Areaid      = Guid.NewGuid().ToString(),
                Nome        = dto.Nome,
                Url         = dto.Url,
                Descricao   = dto.Descricao,
                Areaidpai   = dto.Areaidpai,
                Posicao     = dto.Posicao,
                Tipoarea    = dto.Tipoarea,
                Aplicacaoid = acessoTotal ? dto.Aplicacaoid : claimAppId,
                Datainicial = DateTime.Now
            };
            _context.Areas.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] NovaAreaDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Areas.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal && item.Aplicacaoid != claimAppId) return Forbid();
            item.Nome      = dto.Nome;
            item.Url       = dto.Url;
            item.Descricao = dto.Descricao;
            item.Areaidpai = dto.Areaidpai;
            item.Posicao   = dto.Posicao;
            item.Tipoarea  = dto.Tipoarea;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Areas.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal && item.Aplicacaoid != claimAppId) return Forbid();
            _context.Areas.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class AuthController : Controller
    {
        private readonly CmsxDbContext _context;
        private readonly IConfiguration _config;

        public AuthController(CmsxDbContext context, IConfiguration config)
        {
            _context = context;
            _config = config;
        }

        public class LoginRequest { public string Apelido { get; set; } = ""; public string Senha { get; set; } = ""; }

        public class SignupRequest
        {
            public string Nome { get; set; } = "";
            public string Sobrenome { get; set; } = "";
            public string Apelido { get; set; } = "";
            public string Senha { get; set; } = "";
            public string AppNome { get; set; } = "";
            public string AppUrl { get; set; } = "";
        }

        [HttpPost("signup")]
        public IActionResult Signup([FromBody] SignupRequest req)
        {
            if (_context.Usuarios.Any(u => u.Apelido == req.Apelido))
                return BadRequest(new { message = "Login já está em uso." });

            if (_context.Aplicacaos.Any(a => a.Url == req.AppUrl))
                return BadRequest(new { message = "URL da aplicação já está em uso." });

            var userId = Guid.NewGuid().ToString();
            var appId  = Guid.NewGuid().ToString();

            var usuario = new Usuario
            {
                Userid       = userId,
                Nome         = req.Nome,
                Sobrenome    = req.Sobrenome,
                Apelido      = req.Apelido,
                Senha        = req.Senha,
                Ativo        = 0,
                Datainclusao = DateTime.Now
            };

            var aplicacao = new Aplicacao
            {
                Aplicacaoid     = appId,
                Nome            = req.AppNome,
                Url             = req.AppUrl,
                Idusuarioinicio = userId,
                Datainicio      = DateTime.Now,
                Isactive        = false,
                Layoutchoose    = "_Layout.cshtml"
            };

            var relacao = new Relusuarioaplicacao
            {
                Usuarioid   = userId,
                Aplicacaoid = appId,
                Relacaoid   = Guid.NewGuid().ToString()
            };

            _context.Usuarios.Add(usuario);
            _context.Aplicacaos.Add(aplicacao);
            _context.Relusuarioaplicacaos.Add(relacao);
            _context.SaveChanges();

            return Ok(new { message = "Cadastro realizado com sucesso." });
        }

        [HttpPost("login")]
        public IActionResult Login([FromBody] LoginRequest req)
        {
            var user = _context.Usuarios
                .FirstOrDefault(u => u.Apelido == req.Apelido && u.Senha == req.Senha && u.Ativo == (byte)1);
            if (user == null)
                return Unauthorized(new { message = "Login ou senha inválidos" });

            var grupos = _context.Relusuariogrupos
                .Where(r => r.Usuarioid == user.Userid)
                .Join(_context.Grupos, r => r.Grupoid, g => g.Grupoid, (r, g) => g)
                .ToList();

            bool acessoTotal = grupos.Any(g => g.Acessototal);
            var nomesGrupos  = grupos.Select(g => g.Nome).ToList();

            var apps = _context.Relusuarioaplicacaos
                .Where(r => r.Usuarioid == user.Userid)
                .Select(r => r.Aplicacaoid)
                .ToList();

            var aplicacaoid = apps.FirstOrDefault();

            var app = _context.Aplicacaos.FirstOrDefault(a => a.Aplicacaoid == aplicacaoid);
            bool isDemo = app?.IsDemo ?? false;

            var claims = new[]
            {
                new Claim("userid",      user.Userid ?? ""),
                new Claim("apelido",     user.Apelido ?? ""),
                new Claim("nome",        user.Nome ?? ""),
                new Claim("aplicacaoid", aplicacaoid ?? ""),
                new Claim("acessoTotal", acessoTotal.ToString()),
                new Claim("isDemo",      isDemo.ToString())
            };

            var key   = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_config["Jwt:Key"]!));
            var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);
            var token = new JwtSecurityToken(
                issuer:            _config["Jwt:Issuer"],
                audience:          _config["Jwt:Audience"],
                claims:            claims,
                expires:           DateTime.UtcNow.AddHours(8),
                signingCredentials: creds
            );

            return Ok(new
            {
                token       = new JwtSecurityTokenHandler().WriteToken(token),
                userid      = user.Userid,
                nome        = user.Nome,
                apelido     = user.Apelido,
                acessoTotal,
                grupos      = nomesGrupos,
                aplicacaoid = aplicacaoid,
                isDemo
            });
        }

        // ── Login demo: reseta dados e emite token sem credenciais ───────────
        [HttpPost("demo-login")]
        public IActionResult DemoLogin()
        {
            var user = _context.Usuarios.FirstOrDefault(u => u.Apelido == "demo" && u.Ativo == (byte)1);
            if (user == null)
                return NotFound(new { message = "Tenant demo não configurado. Execute cmsxDB.tenant_demo.sql." });

            var aplicacaoidStr = _context.Relusuarioaplicacaos
                .Where(r => r.Usuarioid == user.Userid)
                .Select(r => r.Aplicacaoid)
                .FirstOrDefault();

            if (aplicacaoidStr == null)
                return StatusCode(500, new { message = "Tenant demo sem aplicação vinculada." });

            // Reset: limpa layouts de todas as áreas do tenant demo
            var areas = _context.Areas.Where(a => a.Aplicacaoid == aplicacaoidStr).ToList();
            foreach (var area in areas)
                area.Layout = "{\"blocos\":[]}";

            // Remove conteúdos do tenant demo
            var areaIds = areas.Select(a => a.Areaid).ToList();
            var conteudos = _context.Conteudos.Where(c => areaIds.Contains(c.Areaid)).ToList();
            _context.Conteudos.RemoveRange(conteudos);

            // Zera uso de IA do dia
            var hoje = DateOnly.FromDateTime(DateTime.Today);
            var usoHoje = _context.IaUsos.Where(u => u.Aplicacaoid == aplicacaoidStr && u.Data == hoje).ToList();
            _context.IaUsos.RemoveRange(usoHoje);

            _context.SaveChanges();

            var claims = new[]
            {
                new Claim("userid",      user.Userid ?? ""),
                new Claim("apelido",     user.Apelido ?? ""),
                new Claim("nome",        "Demo"),
                new Claim("aplicacaoid", aplicacaoidStr),
                new Claim("acessoTotal", "False"),
                new Claim("isDemo",      "True")
            };

            var key   = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_config["Jwt:Key"]!));
            var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);
            var token = new JwtSecurityToken(
                issuer:             _config["Jwt:Issuer"],
                audience:           _config["Jwt:Audience"],
                claims:             claims,
                expires:            DateTime.UtcNow.AddHours(2),
                signingCredentials: creds
            );

            return Ok(new
            {
                token       = new JwtSecurityTokenHandler().WriteToken(token),
                userid      = user.Userid,
                nome        = "Demo",
                apelido     = "demo",
                acessoTotal = false,
                grupos      = new string[0],
                aplicacaoid = aplicacaoidStr,
                isDemo      = true
            });
        }
    }
}

