        {
            var (acessoTotal, claimAppId) = UserContext();
            var q = _context.Formularionews.AsQueryable();

            var filtroAppId = !acessoTotal ? claimAppId : (acessoTotal && !string.IsNullOrEmpty(aplicacaoid) ? aplicacaoid : null);
            if (filtroAppId != null)
            {
                var formularioIds = _context.Formularios
                    .Where(f => _context.Areas
                        .Where(a => a.Aplicacaoid == filtroAppId)
                        .Select(a => a.Areaid)
                        .Contains(f.Areaid))
                    .Select(f => f.Formularioid)
                    .ToHashSet();
                q = q.Where(r => r.Formularioid != null && formularioIds.Contains(r.Formularioid));
            }

            return q.OrderByDescending(f => f.Idform).ToArray();
        }

        [HttpPatch("respostas/{id}/ativo")]
        public IActionResult PatchAtivo(int id, [FromBody] int ativo)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularionews.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Formularios
                    .Where(f => f.Formularioid == item.Formularioid)
                    .Join(_context.Areas, f => f.Areaid, a => a.Areaid, (f, a) => a)
                    .FirstOrDefault();
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            item.Ativo = ativo;
            _context.SaveChanges();
            return Ok();
        }

        [HttpDelete("respostas/{id}")]
        public IActionResult DeleteResposta(int id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularionews.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Formularios
                    .Where(f => f.Formularioid == item.Formularioid)
                    .Join(_context.Areas, f => f.Areaid, a => a.Areaid, (f, a) => a)
                    .FirstOrDefault();
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            _context.Formularionews.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class GruposController : Controller
    {
        private readonly CmsxDbContext _context;
        public GruposController(CmsxDbContext context) { _context = context; }

        private bool IsAdmin() => User.FindFirstValue("acessoTotal") == "True";

        // Grupos são globais — somente admin gerencia
        [HttpGet]
        public IActionResult Get()
        {
            if (!IsAdmin()) return Forbid();
            return Ok(_context.Grupos.OrderBy(g => g.Nome).ToArray());
        }

        [HttpGet("{id}/usuarios")]
        public IActionResult GetUsuarios(string id)
        {
            if (!IsAdmin()) return Forbid();
            var usuarios = _context.Relusuariogrupos
                .Where(r => r.Grupoid == id)
                .AsEnumerable()
                .Join(_context.Usuarios.AsEnumerable(), r => r.Usuarioid, u => u.Userid,
                    (r, u) => new { r.Relacaoid, u.Userid, u.Nome, u.Sobrenome, u.Apelido, u.Ativo })
                .ToList();
            return Ok(usuarios);
        }

        public class NovoGrupoDto
        {
            public string Nome { get; set; } = "";
            public string? Descricao { get; set; }
            public bool Acessototal { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] NovoGrupoDto dto)
        {
            if (!IsAdmin()) return Forbid();
            var item = new Grupo
            {
                Grupoid     = Guid.NewGuid().ToString(),
                Nome        = dto.Nome,
                Descricao   = dto.Descricao,
                Acessototal = dto.Acessototal
            };
            _context.Grupos.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] NovoGrupoDto dto)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.Grupos.Find(id);
            if (item == null) return NotFound();
            item.Nome        = dto.Nome;
            item.Descricao   = dto.Descricao;
            item.Acessototal = dto.Acessototal;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.Grupos.Find(id);
            if (item == null) return NotFound();
            var vinculos = _context.Relusuariogrupos.Where(r => r.Grupoid == id).ToList();
            _context.Relusuariogrupos.RemoveRange(vinculos);
            _context.Grupos.Remove(item);
            _context.SaveChanges();
            return Ok();
        }

        [HttpPost("{id}/usuarios")]
        public IActionResult AddUsuario(string id, [FromBody] string usuarioid)
        {
            if (!IsAdmin()) return Forbid();
            if (_context.Relusuariogrupos.Any(r => r.Grupoid == id && r.Usuarioid == usuarioid))
                return BadRequest(new { message = "Usuário já pertence a este grupo." });

            _context.Relusuariogrupos.Add(new Relusuariogrupo
            {
                Relacaoid = Guid.NewGuid().ToString(),
                Grupoid   = id,
                Usuarioid = usuarioid
            });
            _context.SaveChanges();
            return Ok();
        }

        [HttpDelete("{id}/usuarios/{relacaoid}")]
        public IActionResult RemoveUsuario(string id, string relacaoid)
        {
            if (!IsAdmin()) return Forbid();
            var rel = _context.Relusuariogrupos.Find(relacaoid);
            if (rel == null) return NotFound();
            _context.Relusuariogrupos.Remove(rel);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using System.Text.Json;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class LayoutTemplatesController : ControllerBase
    {
        private readonly CmsxDbContext _context;
        public LayoutTemplatesController(CmsxDbContext context) => _context = context;

        private bool IsAdmin() => User.FindFirstValue("acessoTotal") == "True";

        [HttpGet]
        public IActionResult Get() =>
            Ok(_context.LayoutTemplates.OrderBy(t => t.Nome).ToList());

        [HttpGet("{id}")]
        public IActionResult Get(string id)
        {
            var t = _context.LayoutTemplates.Find(id);
            return t == null ? NotFound() : Ok(t);
        }

        [HttpGet("padrao")]
        public IActionResult GetPadrao([FromQuery] string tipo = "home")
        {
            var t = _context.LayoutTemplates.FirstOrDefault(x => x.Tipo == tipo && x.Padrao);
            return t == null ? NotFound() : Ok(t);
        }

        public class SalvarTemplateDto
        {
            public string Nome { get; set; } = "";
            public string? Descricao { get; set; }
            public string Tipo { get; set; } = "home";
            public string Layout { get; set; } = "";
            public bool Padrao { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] SalvarTemplateDto dto)
        {
            if (!IsAdmin()) return Forbid();

            // Se for padrão, remove o padrão anterior do mesmo tipo
            if (dto.Padrao)
                foreach (var t in _context.LayoutTemplates.Where(x => x.Tipo == dto.Tipo && x.Padrao))
                    t.Padrao = false;

            // Valida o JSON do layout
            try { JsonDocument.Parse(dto.Layout); }
            catch { return BadRequest(new { erro = "Layout JSON inválido." }); }

            var item = new LayoutTemplate
            {
                Templateid   = Guid.NewGuid().ToString(),
                Nome         = dto.Nome,
                Descricao    = dto.Descricao,
                Tipo         = dto.Tipo,
                Layout       = dto.Layout,
                Padrao       = dto.Padrao,
                Datainclusao = DateTime.Now
            };
            _context.LayoutTemplates.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] SalvarTemplateDto dto)
        {
            if (!IsAdmin()) return Forbid();

            var item = _context.LayoutTemplates.Find(id);
            if (item == null) return NotFound();

            if (dto.Padrao)
                foreach (var t in _context.LayoutTemplates.Where(x => x.Tipo == dto.Tipo && x.Padrao && x.Templateid != id))
                    t.Padrao = false;

            item.Nome      = dto.Nome;
            item.Descricao = dto.Descricao;
            item.Tipo      = dto.Tipo;
            item.Layout    = dto.Layout;
            item.Padrao    = dto.Padrao;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.LayoutTemplates.Find(id);
            if (item == null) return NotFound();
            _context.LayoutTemplates.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using CMSAPI.Services;
using CMSXData.Models;
using ICMSX;
using System.Security.Claims;

namespace CMSAPI.Controllers;

[ApiController]
[Route("api/loja")]
[AllowAnonymous]
public class LojaController(
    SalematicHttpService salematic,
    CmsxDbContext db,
    IClienteLojaRepositorio clienteLojaRepo,
    PedidoServiceBusPublisher publisher) : ControllerBase
{

    [HttpGet("resolve")]
    public IActionResult Resolve([FromQuery] string slug)
    {
        if (string.IsNullOrEmpty(slug))
            return BadRequest(new { message = "slug é obrigatório." });

        var app = db.Aplicacaos.FirstOrDefault(a => a.Url == slug);
        if (app == null)
            return NotFound(new { message = $"Site '{slug}' não encontrado." });

        return Ok(new { aplicacaoid = app.Aplicacaoid.ToString(), nomeLoja = app.Nome });
    }

    [HttpGet("catalogo")]
    public async Task<IActionResult> GetProdutos([FromQuery] string aplicacaoid)
    {
        if (string.IsNullOrEmpty(aplicacaoid))
            return BadRequest(new { message = "aplicacaoid é obrigatório." });

        var produtos = await db.Produtos
            .Where(p => p.Aplicacaoid == aplicacaoid)
            .Select(p => new {
                p.Produtoid,
                p.Sku,
                p.Nome,
                p.Descricacurta,
                p.Valor
            })
            .ToListAsync();

        return Ok(produtos);
    }

    [HttpPost("auth/registrar")]
    public async Task<IActionResult> Registrar([FromBody] RegistrarLojaRequest req)
    {
        if (string.IsNullOrEmpty(req.Aplicacaoid))
            return BadRequest(new { message = "aplicacaoid é obrigatório." });

        var auth = await salematic.RegistrarAsync(req);
        if (auth is null)
            return StatusCode(502, new { message = "Falha ao registrar cliente na Salematic." });

        dynamic connProps = new System.Dynamic.ExpandoObject();
        connProps.banco = "SqlServer";
        connProps.parms = 3;
        clienteLojaRepo.MakeConnection(connProps);
        clienteLojaRepo.CriaClienteLoja(new ClienteLoja
        {
            Aplicacaoid        = req.Aplicacaoid,
            SalematicClienteId = auth.ClienteId
        });

        return Ok(auth);
    }

    [HttpPost("auth/login")]
    public async Task<IActionResult> Login([FromBody] LoginLojaRequest req)
    {
        var auth = await salematic.LoginAsync(req);
        if (auth is null)
            return Unauthorized(new { message = "Credenciais inválidas." });

        return Ok(auth);
    }

    [Authorize(AuthenticationSchemes = "Salematic")]
    [HttpPost("pedidos")]
    public async Task<IActionResult> CriarPedido([FromBody] CriarPedidoLojaRequest req)
    {
        if (string.IsNullOrEmpty(req.Numeropedido) || string.IsNullOrEmpty(req.Clienteemail))
            return BadRequest(new { message = "numeropedido e clienteemail são obrigatórios." });

        var pedido = new Pedido
        {
            Pedidoid        = Guid.NewGuid(),
            Aplicacaoid     = req.Aplicacaoid,
            Numeropedido    = req.Numeropedido,
            Clientenome     = req.Clientenome,
            Clienteemail    = req.Clienteemail,
            Valorpedido     = req.Valorpedido,
            MetodoPagamento = req.MetodoPagamento,
            Statusatual     = "pendente",
            Datainclusao    = DateTime.UtcNow
        };

        db.Pedidos.Add(pedido);
        db.Statuspedidos.Add(new Statuspedido
        {
            Statuspedidoid = Guid.NewGuid(),
            Pedidoid       = pedido.Pedidoid,
            Status         = "pendente",
            Descricao      = "Pedido recebido.",
            Datahora       = DateTime.UtcNow
        });
        await db.SaveChangesAsync();

        try
        {
            await publisher.PublicarPedidoAsync(pedido);

            pedido.Statusatual = "criado";
            db.Statuspedidos.Add(new Statuspedido
            {
                Statuspedidoid = Guid.NewGuid(),
                Pedidoid       = pedido.Pedidoid,
                Status         = "criado",
                Descricao      = "Pedido publicado no Service Bus com sucesso.",
                Datahora       = DateTime.UtcNow
            });
            await db.SaveChangesAsync();
        }
        catch (Exception)
        {
            db.Statuspedidos.Add(new Statuspedido
            {
                Statuspedidoid = Guid.NewGuid(),
                Pedidoid       = pedido.Pedidoid,
                Status         = "erro_envio",
                Descricao      = "Falha ao publicar no Service Bus. Pedido pendente de reenvio.",
                Datahora       = DateTime.UtcNow
            });
            pedido.Statusatual = "erro_envio";
            await db.SaveChangesAsync();
        }

        return Created($"/api/loja/pedidos/{pedido.Pedidoid}/timeline", new
        {
            pedido.Pedidoid,
            pedido.Numeropedido,
            pedido.Statusatual
        });
    }

    [Authorize(AuthenticationSchemes = "Salematic")]
    [HttpGet("pedidos/{id:guid}/timeline")]
    public async Task<IActionResult> GetTimeline(Guid id)
    {
        var clienteEmail = User.FindFirst("email")?.Value
                    ?? User.FindFirst(ClaimTypes.Email)?.Value;

        var pedido = await db.Pedidos
            .Include(p => p.Statuspedidos)
            .FirstOrDefaultAsync(p => p.Pedidoid == id);

        if (pedido is null)
            return NotFound(new { message = "Pedido não encontrado." });

        if (pedido.Clienteemail != clienteEmail)
            return Forbid();

        var timeline = pedido.Statuspedidos
            .OrderBy(s => s.Datahora)
            .Select(s => new { s.Status, s.Descricao, s.Datahora });

        return Ok(new
        {
            pedido.Pedidoid,
            pedido.Numeropedido,
            pedido.Statusatual,
            timeline
        });
    }

    [Authorize(AuthenticationSchemes = "Salematic")]
    [HttpGet("meus-pedidos")]
    public IActionResult MeusPedidos()
    {
        var clienteEmail = User.FindFirst("email")?.Value
                    ?? User.FindFirst(ClaimTypes.Email)?.Value;

        if(string.IsNullOrEmpty(clienteEmail))
            return Unauthorized(new { message = "Email nao encontrado" });

        var pedidos = db.Pedidos
            .Where(p => p.Clienteemail == clienteEmail)
            .OrderByDescending(p => p.Datainclusao)
            .Select(p => new {
                p.Pedidoid,
                p.Aplicacaoid,
                p.Numeropedido,
                p.Clientenome,
                p.Clienteemail,
                p.Valorpedido,
                p.Statusatual,
                p.Datainclusao
            })
            .ToArray();

        return Ok(pedidos);
    }
}

using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class MediaController : Controller
    {
        private readonly IConfiguration _config;
        private const long MaxBytes = 5 * 1024 * 1024; // 5 MB
        private static readonly string[] TiposPermitidos =
            ["image/jpeg", "image/png", "image/webp", "image/svg+xml", "image/gif"];

        public MediaController(IConfiguration config) => _config = config;

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        private BlobContainerClient GetContainer()
        {
            var connStr = _config["AzureStorage:ConnectionString"]!;
            var container = _config["AzureStorage:Container"] ?? "cms-imagens";
            return new BlobContainerClient(connStr, container);
        }

        private string ResolverTenant(bool acessoTotal, string? claimAppId, string? queryAppId)
        {
            if (acessoTotal && !string.IsNullOrEmpty(queryAppId)) return queryAppId;
            return claimAppId ?? "global";
        }

        [HttpGet]
        public async Task<IActionResult> Listar([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var tenant = ResolverTenant(acessoTotal, claimAppId, aplicacaoid);
            var prefix = tenant + "/";
            var container = GetContainer();
            var result = new List<object>();
            await foreach (var blob in container.GetBlobsAsync(prefix: prefix))
            {
                result.Add(new
                {
                    nome = blob.Name[prefix.Length..],
                    blobName = blob.Name,
                    url = $"{container.Uri}/{blob.Name}",
                    tamanho = blob.Properties.ContentLength ?? 0,
                    data = blob.Properties.CreatedOn
                });
            }
            return Ok(result);
        }

        [HttpPost("upload")]
        public async Task<IActionResult> Upload([FromQuery] string? aplicacaoid, IFormFile arquivo)
        {
            if (arquivo == null || arquivo.Length == 0)
                return BadRequest(new { erro = "Nenhum arquivo enviado." });
            if (arquivo.Length > MaxBytes)
                return BadRequest(new { erro = "Arquivo muito grande. Limite: 5 MB." });
            if (!TiposPermitidos.Contains(arquivo.ContentType))
                return BadRequest(new { erro = "Tipo não permitido. Use JPG, PNG, WebP, SVG ou GIF." });

            var (acessoTotal, claimAppId) = UserContext();
            var tenant = ResolverTenant(acessoTotal, claimAppId, aplicacaoid);
            var ext = Path.GetExtension(arquivo.FileName);
            var blobName = $"{tenant}/{Guid.NewGuid()}{ext}";

            var container = GetContainer();
            var blob = container.GetBlobClient(blobName);
            var opts = new BlobUploadOptions
            {
                HttpHeaders = new BlobHttpHeaders { ContentType = arquivo.ContentType }
            };
            using var stream = arquivo.OpenReadStream();
            await blob.UploadAsync(stream, opts);

            return Ok(new { url = blob.Uri.ToString(), blobName, nome = Path.GetFileName(blobName) });
        }

        [HttpDelete]
        public async Task<IActionResult> Deletar([FromQuery] string blobName)
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (!acessoTotal && !blobName.StartsWith(claimAppId + "/"))
                return Forbid();
            var container = GetContainer();
            await container.GetBlobClient(blobName).DeleteIfExistsAsync();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class ModulosController : Controller
    {
        private readonly CmsxDbContext _context;
        public ModulosController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        [HttpGet]
        public IEnumerable<Modulo> Get([FromQuery] string? usuarioid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();

            // Filtro por usuário específico (para montar menu)
            if (!string.IsNullOrEmpty(usuarioid))
            {
                return _context.Relmodulousuarios
                    .Where(r => r.Usuarioid == usuarioid)
                    .Join(_context.Modulos, r => r.Moduloid, m => m.Moduloid, (r, m) => m)
                    .OrderBy(m => m.Posicao)
                    .ToArray();
            }

            // Admin: todos os módulos
            if (acessoTotal)
                return _context.Modulos.OrderBy(m => m.Posicao).ToArray();

            // Tenant: apenas módulos vinculados à sua aplicação
            return _context.Relmoduloaplicacaos
                .Where(r => r.Aplicacaoid == claimAppId)
                .AsEnumerable()
                .Join(_context.Modulos.AsEnumerable(), r => r.Moduloid, m => m.Moduloid, (r, m) => m)
                .OrderBy(m => m.Posicao)
                .ToArray();
        }
    }
}

using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using CMSXData.Models;
using CMSAPI.Services;
using ICMSX;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class PageBuilderController : Controller
    {
        private readonly CmsxDbContext _context;
        private readonly IAgentIAFactory _agentFactory;
        private readonly IConfiguration _config;
        private readonly IHttpClientFactory _httpClientFactory;

        public PageBuilderController(CmsxDbContext context, IAgentIAFactory agentFactory, IConfiguration config, IHttpClientFactory httpClientFactory)
        {
            _context = context;
            _agentFactory = agentFactory;
            _config = config;
            _httpClientFactory = httpClientFactory;
        }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        // ── Catálogo de blocos ───────────────────────────────────────────────

        [AllowAnonymous]
        [HttpGet("blocos")]
        public IActionResult GetBlocos() =>
            Ok(_context.DictBlocos.OrderBy(b => b.Nome).ToArray());

        // ── Resumo de layouts salvos ─────────────────────────────────────────

        [Authorize]
        [HttpGet("layouts-resumo")]
        public IActionResult GetLayoutsResumo([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var query = _context.Areas.AsQueryable();

            if (!acessoTotal)
                query = query.Where(a => a.Aplicacaoid == claimAppId);
            else if (!string.IsNullOrEmpty(aplicacaoid))
                query = query.Where(a => a.Aplicacaoid == aplicacaoid);

            var areas = query
                .Where(a => a.Layout != null && a.Layout != "{\"blocos\":[]}")
                .Select(a => new { a.Areaid, a.Nome, a.Layout })
                .ToList()
                .Select(a => {
                    int qtd = 0;
                    try { qtd = JsonDocument.Parse(a.Layout!).RootElement.GetProperty("blocos").GetArrayLength(); } catch { }
                    return new { a.Areaid, a.Nome, QtdBlocos = qtd };
                });
            return Ok(areas);
        }

        // ── Layout de uma área ───────────────────────────────────────────────

        [Authorize]
        [HttpGet("layout/{areaid}")]
        public IActionResult GetLayout(string areaid)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var area = _context.Areas.FirstOrDefault(a => a.Areaid == areaid);
            if (area == null) return NotFound();
            if (!acessoTotal && area.Aplicacaoid != claimAppId) return Forbid();

            return Ok(new { area.Areaid, area.Nome, layout = area.Layout ?? "{\"blocos\":[]}", version = area.PageBuilderVersion ?? "v1" });
        }

        [Authorize]
        [HttpPut("layout/{areaid}")]
        public IActionResult SaveLayout(string areaid, [FromBody] JsonElement payload)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var area = _context.Areas.FirstOrDefault(a => a.Areaid == areaid);
            if (area == null) return NotFound();
            if (!acessoTotal && area.Aplicacaoid != claimAppId) return Forbid();

            area.Layout = payload.GetRawText();
            _context.SaveChanges();
            return Ok();
        }

        // ── Contexto para o agente IA ────────────────────────────────────────

        [Authorize]
        [HttpGet("contexto-ia")]
        public IActionResult GetContextoIA()
        {
            var (acessoTotal, claimAppId) = UserContext();

            var blocos = _context.DictBlocos
                .OrderBy(b => b.Nome)
                .Select(b => new { b.Tipobloco, b.Nome, b.Descricao, b.SchemaConfig })
                .ToList();

            var areas = _context.Areas
                .Where(a => acessoTotal || a.Aplicacaoid == claimAppId)
                .Select(a => new { a.Areaid, a.Nome })
                .ToList();

            var formularios = _context.Formularios
                .Where(f => _context.Areas
                    .Where(a => acessoTotal || a.Aplicacaoid == claimAppId)
                    .Select(a => a.Areaid)
                    .Contains(f.Areaid))
                .Select(f => new { f.Formularioid, f.Nome })
                .ToList();

