using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Text.Json;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class SiteController : ControllerBase
    {
        private readonly CmsxDbContext _context;

        public SiteController(CmsxDbContext context) => _context = context;

        [AllowAnonymous]
        [HttpGet("slug/{slug}")]
        public IActionResult GetBySlug(string slug)
        {
            var app = _context.Aplicacaos.FirstOrDefault(a => a.Url == slug);
            return app == null ? NotFound(new { erro = $"Site '{slug}' não encontrado." }) : BuildSiteData(app);
        }

        [Authorize]
        [HttpGet("preview/{aplicacaoid}")]
        public IActionResult GetPreview(string aplicacaoid)
        {
            var app = _context.Aplicacaos.FirstOrDefault(a => a.Aplicacaoid.ToString() == aplicacaoid);
            return app == null ? NotFound() : BuildSiteData(app);
        }

        private IActionResult BuildSiteData(Aplicacao app)
        {
            var areas = _context.Areas
                .Where(a => a.Aplicacaoid == app.Aplicacaoid.ToString())
                .OrderBy(a => a.Posicao).ThenBy(a => a.Nome)
                .ToList();

            var areasResult = areas.Select(area =>
            {
                var blocos = new List<object>();
                if (!string.IsNullOrEmpty(area.Layout) && area.Layout != "{\"blocos\":[]}")
                {
                    try
                    {
                        var doc = JsonDocument.Parse(area.Layout);
                        foreach (var b in doc.RootElement.GetProperty("blocos").EnumerateArray())
                        {
                            var tipo = b.GetProperty("tipo").GetString() ?? "";
                            var configRaw = b.GetProperty("config").GetRawText();
                            var config = JsonDocument.Parse(configRaw).RootElement;
                            var coluna = b.TryGetProperty("coluna", out var colunaEl) ? colunaEl.GetString() : null;
                            var dados = EnriquecerBloco(tipo, config, app.Aplicacaoid.ToString());
                            blocos.Add(new { tipo, config = JsonSerializer.Deserialize<object>(configRaw), coluna, dados });
                        }
                    }
                    catch { }
                }
                return new { area.Areaid, area.Nome, area.Url, TemLayout = blocos.Count > 0, blocos };
            }).ToList();

            return Ok(new { Aplicacaoid = app.Aplicacaoid.ToString(), app.Nome, app.Url, app.Header, areas = areasResult });
        }

        private object? EnriquecerBloco(string tipo, JsonElement config, string aplicacaoid)
        {
            switch (tipo)
            {
                case "lista-conteudos":
                {
                    var areaid = Str(config, "areaid");
                    if (string.IsNullOrEmpty(areaid)) return null;
                    return _context.Conteudos
                        .Where(c => c.Areaid == areaid)
                        .OrderByDescending(c => c.Datainclusao)
                        .Take(Int(config, "limite", 6))
                        .Select(c => new { c.Conteudoid, c.Titulo, c.Texto, c.Autor, c.Datainclusao })
                        .ToList();
                }
                case "lista-produtos":
                {
                    var catid = Str(config, "cateriaid");
                    var q = _context.Produtos.Where(p => p.Aplicacaoid == aplicacaoid);
                    if (!string.IsNullOrEmpty(catid)) q = q.Where(p => p.Cateriaid == catid);
                    return q.Take(Int(config, "limite", 8))
                        .Select(p => new {
                            p.Produtoid, p.Nome, p.Descricacurta, p.Valor,
                            Imagem = _context.Imagems.Where(i => i.Parentid == p.Produtoid).Select(i => i.Url).FirstOrDefault()
                        }).ToList();
                }
                case "categorias":
                {
                    var pai = Str(config, "cateriaidpai");
                    return _context.Cateria
                        .Where(c => c.Aplicacaoid == aplicacaoid &&
                            (string.IsNullOrEmpty(pai) ? c.Cateriaidpai == null : c.Cateriaidpai == pai))
                        .Select(c => new { c.Cateriaid, c.Nome, c.Descricao })
                        .ToList();
                }
                case "faq":
                {
                    var formularioid = Str(config, "formularioid");
                    if (string.IsNullOrEmpty(formularioid)) return null;
                    return _context.Faqs
                        .Where(f => f.Formularioid == formularioid && f.Ativo)
                        .OrderBy(f => f.Ordem)
                        .Select(f => new { f.Faqid, f.Pergunta, f.Resposta })
                        .ToList();
                }
                case "formulario":
                {
                    var formularioid = Str(config, "formularioid");
                    if (string.IsNullOrEmpty(formularioid)) return null;
                    var f = _context.Formularios.FirstOrDefault(x => x.Formularioid == formularioid);
                    return f == null ? null : new { f.Formularioid, f.Nome, f.Valor };
                }
                case "menu-navegacao":
                {
                    return _context.Areas
                        .Where(a => a.Aplicacaoid == aplicacaoid && !string.IsNullOrEmpty(a.Url))
                        .OrderBy(a => a.Posicao).ThenBy(a => a.Nome)
                        .Select(a => new { a.Areaid, a.Nome, a.Url })
                        .ToList();
                }
                case "prova-social":
                case "video":
                case "contador":
                case "hero-cta":
                case "rodape":
                    return null; // config-only blocks, no DB enrichment needed
                default: return null;
            }
        }

        private static string? Str(JsonElement el, string key) =>
            el.TryGetProperty(key, out var v) ? v.GetString() : null;

        private static int Int(JsonElement el, string key, int def) =>
            el.TryGetProperty(key, out var v) && v.TryGetInt32(out var n) ? n : def;
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSXData.Models;

namespace CMSAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class UsuariosController : Controller
    {
        private readonly CmsxDbContext _context;
        public UsuariosController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        private static Guid? ParseGuid(string? s) =>
            s != null && Guid.TryParse(s, out var g) ? g : null;

        [HttpGet]
        public IEnumerable<object> Get([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();

            if (acessoTotal)
            {
                if (!string.IsNullOrEmpty(aplicacaoid))
                {
                    var adminSet = _context.Relusuariogrupos
                        .Join(_context.Grupos, r => r.Grupoid, g => g.Grupoid, (r, g) => new { r.Usuarioid, g.Acessototal })
                        .Where(x => x.Acessototal)
                        .Select(x => x.Usuarioid)
                        .ToHashSet();

                    return _context.Relusuarioaplicacaos
                        .Where(r => r.Aplicacaoid == aplicacaoid)
                        .Join(_context.Usuarios, r => r.Usuarioid, u => u.Userid,
                            (r, u) => new { u.Userid, u.Nome, u.Sobrenome, u.Apelido, u.Ativo, u.Datainclusao })
                        .AsEnumerable()
                        .Where(u => !adminSet.Contains(u.Userid))
                        .ToArray();
                }

                return _context.Usuarios
                    .Select(u => new { u.Userid, u.Nome, u.Sobrenome, u.Apelido, u.Ativo, u.Datainclusao })
                    .ToArray();
            }

            // Tenant: retorna usuários da sua aplicação excluindo admins
            var adminIds = _context.Relusuariogrupos
                .Join(_context.Grupos, r => r.Grupoid, g => g.Grupoid, (r, g) => new { r.Usuarioid, g.Acessototal })
                .Where(x => x.Acessototal)
                .Select(x => x.Usuarioid)
                .ToHashSet();

            return _context.Relusuarioaplicacaos
                .Where(r => r.Aplicacaoid == claimAppId)
                .Join(_context.Usuarios, r => r.Usuarioid, u => u.Userid,
                    (r, u) => new { u.Userid, u.Nome, u.Sobrenome, u.Apelido, u.Ativo, u.Datainclusao })
                .AsEnumerable()
                .Where(u => !adminIds.Contains(u.Userid))
                .ToArray();
        }

        public class NovoUsuarioDto
        {
            public string Nome { get; set; } = "";
            public string Sobrenome { get; set; } = "";
            public string? Apelido { get; set; }
            public string? Senha { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] NovoUsuarioDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();

            var usuario = new Usuario
            {
                Userid       = Guid.NewGuid().ToString(),
                Nome         = dto.Nome,
                Sobrenome    = dto.Sobrenome,
                Apelido      = dto.Apelido,
                Senha        = dto.Senha,
                Ativo        = 1,
                Datainclusao = DateTime.Now
            };
            _context.Usuarios.Add(usuario);

            // Tenant: vincula o novo usuário automaticamente à sua aplicação
            if (!acessoTotal && !string.IsNullOrEmpty(claimAppId))
            {
                _context.Relusuarioaplicacaos.Add(new Relusuarioaplicacao
                {
                    Relacaoid   = Guid.NewGuid().ToString(),
                    Usuarioid   = usuario.Userid,
                    Aplicacaoid = claimAppId
                });
            }

            _context.SaveChanges();
            return Ok(usuario);
        }

        public class EditarUsuarioDto
        {
            public string Nome { get; set; } = "";
            public string Sobrenome { get; set; } = "";
            public string? Apelido { get; set; }
            public string? Senha { get; set; }
            public byte? Ativo { get; set; }
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] EditarUsuarioDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var user = _context.Usuarios.Find(id);
            if (user == null) return NotFound();

            if (!acessoTotal)
            {
                var pertence = _context.Relusuarioaplicacaos
                    .Any(r => r.Usuarioid == id && r.Aplicacaoid == claimAppId);
                if (!pertence) return Forbid();
            }

            user.Nome      = dto.Nome;
            user.Sobrenome = dto.Sobrenome;
            user.Apelido   = dto.Apelido;
            user.Ativo     = dto.Ativo;
            if (!string.IsNullOrWhiteSpace(dto.Senha))
                user.Senha = dto.Senha;
            _context.SaveChanges();
            return Ok(user);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var user = _context.Usuarios.Find(id);
            if (user == null) return NotFound();

            if (!acessoTotal)
            {
                var pertence = _context.Relusuarioaplicacaos
                    .Any(r => r.Usuarioid == id && r.Aplicacaoid == claimAppId);
                if (!pertence) return Forbid();
            }

            _context.Usuarios.Remove(user);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using CMSAPI.Services.Agents;
using ICMSX;

namespace CMSAPI.Services;

public class AgentIAFactory : IAgentIAFactory
{
    private readonly IConfiguration _config;
    private readonly IHttpClientFactory _httpFactory;

    public AgentIAFactory(IConfiguration config, IHttpClientFactory httpFactory)
    {
        _config = config;
        _httpFactory = httpFactory;
    }

    public IAgentIA Criar(string? provedor = null, string? tenantApiKey = null, string? tenantModelo = null)
    {
        var alvo = (provedor ?? _config["AgentIA:Default"] ?? "gemini").ToLowerInvariant();

        return alvo switch
        {
            "gemini" => new GeminiAgent(
                tenantApiKey ?? ChaveOuErro("AgentIA:Gemini:ApiKey", "Gemini"),
                tenantModelo ?? _config["AgentIA:Gemini:Model"] ?? "gemini-2.0-flash",
                _config["AgentIA:Gemini:BaseUrl"] ?? "https://generativelanguage.googleapis.com/v1beta/models",
                _httpFactory),
            "anthropic" => new AnthropicAgent(
                tenantApiKey ?? ChaveOuErro("AgentIA:Anthropic:ApiKey", "Anthropic"),
                tenantModelo ?? _config["AgentIA:Anthropic:Model"] ?? "claude-haiku-4-5-20251001",
                _config["AgentIA:Anthropic:Url"] ?? "https://api.anthropic.com/v1/messages",
                _httpFactory),
            _ => throw new NotSupportedException($"Provedor de IA desconhecido: '{alvo}'. Use 'anthropic' ou 'gemini'.")
        };
    }

    private string ChaveOuErro(string path, string nome)
    {
        var key = _config[path];
        if (string.IsNullOrWhiteSpace(key))
            throw new InvalidOperationException($"ApiKey do {nome} não configurada em appsettings.json (caminho: {path}).");
        return key;
    }
}

