        _app.DataFinal = dr["DataFinal"].ToString();
        if (dr.Table.Columns.Contains("mailUser"))
        {
            _app.mailUser = dr["mailUser"].ToString();
            _app.PagSeguroToken = dr["PagSeguroToken"].ToString();
