                RoteiroBLL _rot = RoteiroBLL.ObtemRoteiro();
                _rot.fornecedor = dr["fornecedor"].ToString();
                _rot.idFornecedor = int.Parse(dr["idfornecedor"].ToString());
                rotLista.Add(_rot);
            }
            return rotLista;
        }

