        {
            List<RoteiroBLL> rotLista = new List<RoteiroBLL>();

            foreach (DataRow dr in dal.ListaDetalheRoteiro().Rows)
            {
                RoteiroBLL _rot = RoteiroBLL.ObtemRoteiro();
