        {
            DropDownList ddl = (DropDownList)e.Row.Cells[0].FindControl("ddlRot");
            ddl.Attributes.Add("onChange", "javascript:return gotoPage('" + ddl.ClientID + "',this.options[this.options.selectedIndex].value);");

