            var lst = (from dr in _detrot
                        where (dr.idTabrot == idrot)
                        select new
                        {
                            idcido = dr.idCidOrig + ";" + idrot,
                            cdorg = dr.cidadeorigem
                        }).Distinct();

            ddl.DataTextField = "cdorg";
            ddl.DataValueField = "idcido";
            ddl.DataSource = lst;
            ddl.DataBind();
