        {
            itemDescription = itemDescription.ToLower();
            foreach (KeyValuePair<string, string> pair in AvailableItemKeysList)
            {
                if (itemDescription.Equals(pair.Value.ToLower()))
                {
                    return pair.Key;
                }
            }
            return null;
