    protected void btnstatus_Command(object sender, CommandEventArgs e)
    {
        if (e.CommandName == "InativarAplicacao")
        {
            _obj.parms = 2;
            _obj.appId = e.CommandArgument.ToString();
            _obj.act = 0;
            _apprepo.MakeConnection(_obj);
            _apprepo.InativaAplicacao();
            ListaAplicacao();
