protected void CarregaRedes()
{
    using (CMSXDB.cmsxDBEntities ctxt = new CMSXDB.cmsxDBEntities())
    {
        var lst = from s in ctxt.dict_socialmedia
                  select s;

        if (lst.Count() >= 1)
        {
            rptRedes.DataSource = lst.ToList();
            rptRedes.DataBind();
        }
    }

}

