                dbLoc.Conteudos.Add(ct);
                dbLoc.SaveChanges();

                var img = (from i in dbLoc.Imagems
                              where i.Imagemid == cnt.UrlImg
                              select new Imagem()
                              {
                                  ImagemId = new Guid(i.Imagemid),
