        }

        public List<Modulo> ListaModulos()
        {
            List<Modulo> modlista = Helper(dal.ListaModulos());
            return modlista;
        }

        public List<Modulo> ListaModulosXUser()
        {
            List<Modulo> modlista = Helper(dal.ListaModulosXUser());
            return modlista;
