                .Where(a => a.Aplicacaoid == filtroId)
                .Select(a => a.Areaid)
                .ToHashSet();

            return Ok(new
            {
                usuarios   = _context.Relusuarioaplicacaos.Count(r => r.Aplicacaoid == filtroId),
                aplicacoes = _context.Aplicacaos.Count(a => a.Aplicacaoid == filtroId),
