using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSUI.Models;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class FaqController : Controller
    {
        private readonly CmsxDbContext _context;
        public FaqController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        // ── Wiki pública ─────────────────────────────────────────────────────

        [AllowAnonymous]
        [HttpGet("wiki/{aplicacaoid}")]
        public IActionResult GetWiki(string aplicacaoid)
        {
            var categorias = _context.Cateria
                .Where(c => c.Aplicacaoid == aplicacaoid)
                .Select(c => new { c.Cateriaid, c.Nome, c.Cateriaidpai })
                .AsEnumerable()
                .Select(c => (c.Cateriaid, c.Nome, c.Cateriaidpai))
                .ToList();

            var formularios = _context.Formularios
                .Where(f => f.Categoriaid != null &&
                            _context.Areas
                                .Where(a => a.Aplicacaoid == aplicacaoid)
                                .Select(a => a.Areaid)
                                .Contains(f.Areaid))
                .Select(f => new { f.Formularioid, f.Nome, f.Categoriaid })
                .AsEnumerable()
                .Select(f => (f.Formularioid, f.Nome, f.Categoriaid))
                .ToList();

            var formularioIds = formularios.Select(f => f.Formularioid).ToHashSet();

            var faqs = _context.Faqs
                .Where(faq => faq.Ativo && formularioIds.Contains(faq.Formularioid))
                .OrderBy(faq => faq.Ordem)
                .AsEnumerable()
                .Select(faq => new FaqWiki(faq.Faqid, faq.Formularioid, faq.Pergunta, faq.Resposta, faq.Ordem))
                .ToList();

            var arvore = categorias
                .Where(c => c.Cateriaidpai == null)
                .Select(c => MontarNo(c.Cateriaid, c.Nome, categorias, formularios, faqs))
                .ToList();

            return Ok(arvore);
        }

        private record CategoriaWiki(string Cateriaid, string? Nome, List<CategoriaWiki> Subcategorias, List<FormularioWiki> Formularios);
        private record FormularioWiki(string Formularioid, string? Nome, List<FaqWiki> Items);
        private record FaqWiki(string Faqid, string Formularioid, string Pergunta, string Resposta, int Ordem);

        private CategoriaWiki MontarNo(
            string cateriaid, string? nome,
            IReadOnlyList<(string Cateriaid, string? Nome, string? Cateriaidpai)> categorias,
            IReadOnlyList<(string Formularioid, string? Nome, string? Categoriaid)> formularios,
            IReadOnlyList<FaqWiki> faqs)
        {
            var subcats = categorias
                .Where(c => c.Cateriaidpai == cateriaid)
                .Select(c => MontarNo(c.Cateriaid, c.Nome, categorias, formularios, faqs))
                .ToList();

            var forms = formularios
                .Where(f => f.Categoriaid == cateriaid)
                .Select(f => new FormularioWiki(
                    f.Formularioid, f.Nome,
                    faqs.Where(faq => faq.Formularioid == f.Formularioid).ToList()))
                .ToList();

            return new CategoriaWiki(cateriaid, nome, subcats, forms);
        }

        // ── CRUD autenticado ─────────────────────────────────────────────────

        [Authorize]
        [HttpGet("{formularioid}")]
        public IActionResult GetByFormulario(string formularioid)
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (!acessoTotal && !TemAcesso(formularioid, claimAppId)) return Forbid();

            var items = _context.Faqs
                .Where(f => f.Formularioid == formularioid)
                .OrderBy(f => f.Ordem)
                .ToArray();
            return Ok(items);
        }

        public class FaqDto
        {
            public string? Pergunta { get; set; }
            public string? Resposta { get; set; }
            public int Ordem { get; set; }
        }

        [Authorize]
        [HttpPost("{formularioid}")]
        public IActionResult Post(string formularioid, [FromBody] FaqDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (!acessoTotal && !TemAcesso(formularioid, claimAppId)) return Forbid();

            var item = new Faq
            {
                Faqid        = Guid.NewGuid().ToString(),
                Formularioid = formularioid,
                Pergunta     = dto.Pergunta ?? "",
                Resposta     = dto.Resposta ?? "",
                Ordem        = dto.Ordem,
                Ativo        = true,
                Datainclusao = DateTime.Now
            };
            _context.Faqs.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [Authorize]
        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] FaqDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Faqs.FirstOrDefault(f => f.Faqid == id);
            if (item == null) return NotFound();
            if (!acessoTotal && !TemAcesso(item.Formularioid, claimAppId)) return Forbid();

            item.Pergunta = dto.Pergunta ?? item.Pergunta;
            item.Resposta = dto.Resposta ?? item.Resposta;
            item.Ordem    = dto.Ordem;
            _context.SaveChanges();
            return Ok(item);
        }

        [Authorize]
        [HttpPatch("{id}/ativo")]
        public IActionResult PatchAtivo(string id, [FromBody] bool ativo)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Faqs.FirstOrDefault(f => f.Faqid == id);
            if (item == null) return NotFound();
            if (!acessoTotal && !TemAcesso(item.Formularioid, claimAppId)) return Forbid();

            item.Ativo = ativo;
            _context.SaveChanges();
            return Ok();
        }

        [Authorize]
        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Faqs.FirstOrDefault(f => f.Faqid == id);
            if (item == null) return NotFound();
            if (!acessoTotal && !TemAcesso(item.Formularioid, claimAppId)) return Forbid();

            _context.Faqs.Remove(item);
            _context.SaveChanges();
            return Ok();
        }

        // ── Promoção de resposta do inbox para FAQ ───────────────────────────

        [Authorize]
        [HttpPost("promover/{idform}")]
        public IActionResult Promover(int idform, [FromBody] FaqDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var resposta = _context.Formularionews.Find(idform);
            if (resposta == null) return NotFound();
            if (!acessoTotal && !TemAcesso(resposta.Formularioid, claimAppId)) return Forbid();

            var item = new Faq
            {
                Faqid        = Guid.NewGuid().ToString(),
                Formularioid = resposta.Formularioid!,
                Pergunta     = dto.Pergunta ?? "",
                Resposta     = dto.Resposta ?? resposta.Texto ?? "",
                Ordem        = dto.Ordem,
                Ativo        = true,
                Datainclusao = DateTime.Now
            };
            _context.Faqs.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        // ── Helper ───────────────────────────────────────────────────────────

        private bool TemAcesso(string? formularioid, string? claimAppId)
        {
            if (string.IsNullOrEmpty(formularioid)) return false;
            return _context.Formularios
                .Where(f => f.Formularioid == formularioid)
                .Join(_context.Areas, f => f.Areaid, a => a.Areaid, (f, a) => a)
                .Any(a => a.Aplicacaoid == claimAppId);
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSUI.Models;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class FormulariosController : Controller
    {
        private readonly CmsxDbContext _context;
        public FormulariosController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        // ── Definições de formulário ─────────────────────────────────────────

        [HttpGet("defs")]
        public IEnumerable<object> GetDefs([FromQuery] string? areaid = null, [FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var q = _context.Formularios.AsQueryable();

            if (!acessoTotal)
            {
                var areasIds = _context.Areas
                    .Where(a => a.Aplicacaoid == claimAppId)
                    .Select(a => a.Areaid)
                    .ToHashSet();
                q = q.Where(f => f.Areaid != null && areasIds.Contains(f.Areaid));
            }
            else if (!string.IsNullOrEmpty(aplicacaoid))
            {
                var areasIds = _context.Areas
                    .Where(a => a.Aplicacaoid == aplicacaoid)
                    .Select(a => a.Areaid)
                    .ToHashSet();
                q = q.Where(f => f.Areaid != null && areasIds.Contains(f.Areaid));
            }

            if (!string.IsNullOrEmpty(areaid))
                q = q.Where(f => f.Areaid == areaid);

            return q.OrderBy(f => f.Nome)
                    .Select(f => new { f.Formularioid, f.Nome, f.Valor, f.Ativo, f.Datainclusao, f.Areaid, f.Categoriaid })
                    .ToArray();
        }

        public class FormularioDefDto
        {
            public string? Nome { get; set; }
            public string? Valor { get; set; }
            public string? Areaid { get; set; }
            public string? Categoriaid { get; set; }
        }

        [HttpPost("defs")]
        public IActionResult PostDef([FromBody] FormularioDefDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (!acessoTotal && !string.IsNullOrEmpty(dto.Areaid))
            {
                var area = _context.Areas.Find(dto.Areaid);
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }

            var item = new Formulario
            {
                Formularioid = Guid.NewGuid().ToString(),
                Nome         = dto.Nome ?? "",
                Valor        = dto.Valor,
                Areaid       = dto.Areaid,
                Categoriaid  = dto.Categoriaid,
                Ativo        = true,
                Datainclusao = DateTime.Now
            };
            _context.Formularios.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("defs/{id}")]
        public IActionResult PutDef(string id, [FromBody] FormularioDefDto dto)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularios.FirstOrDefault(f => f.Formularioid == id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Areas.Find(item.Areaid);
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            item.Nome       = dto.Nome ?? item.Nome;
            item.Valor      = dto.Valor;
            item.Areaid     = dto.Areaid;
            item.Categoriaid = dto.Categoriaid;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("defs/{id}")]
        public IActionResult DeleteDef(string id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularios.FirstOrDefault(f => f.Formularioid == id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Areas.Find(item.Areaid);
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            _context.Formularios.Remove(item);
            _context.SaveChanges();
            return Ok();
        }

        // ── Submissão pública (sem autenticação) ─────────────────────────────

        [AllowAnonymous]
        [HttpPost("{formularioid}/submit")]
        public IActionResult Submit(string formularioid, [FromBody] Dictionary<string, string> campos)
        {
            var formulario = _context.Formularios.FirstOrDefault(f => f.Formularioid == formularioid);
            if (formulario == null) return NotFound();

            var item = new Formularionew
            {
                Formularioid = formularioid,
                Texto        = System.Text.Json.JsonSerializer.Serialize(campos),
                Nome         = campos.GetValueOrDefault("nome") ?? campos.GetValueOrDefault("Nome"),
                Email        = campos.GetValueOrDefault("email") ?? campos.GetValueOrDefault("Email"),
                Telefone     = campos.GetValueOrDefault("telefone") ?? campos.GetValueOrDefault("Telefone"),
                Ativo        = 1
            };
            _context.Formularionews.Add(item);
            _context.SaveChanges();
            return Ok();
        }

        // ── Respostas ────────────────────────────────────────────────────────

        [HttpGet("respostas")]
        public IEnumerable<Formularionew> GetRespostas([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var q = _context.Formularionews.AsQueryable();

            var filtroAppId = !acessoTotal ? claimAppId : (acessoTotal && !string.IsNullOrEmpty(aplicacaoid) ? aplicacaoid : null);
            if (filtroAppId != null)
            {
                var formularioIds = _context.Formularios
                    .Where(f => _context.Areas
                        .Where(a => a.Aplicacaoid == filtroAppId)
                        .Select(a => a.Areaid)
                        .Contains(f.Areaid))
                    .Select(f => f.Formularioid)
                    .ToHashSet();
                q = q.Where(r => r.Formularioid != null && formularioIds.Contains(r.Formularioid));
            }

            return q.OrderByDescending(f => f.Idform).ToArray();
        }

        [HttpPatch("respostas/{id}/ativo")]
        public IActionResult PatchAtivo(int id, [FromBody] int ativo)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularionews.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Formularios
                    .Where(f => f.Formularioid == item.Formularioid)
                    .Join(_context.Areas, f => f.Areaid, a => a.Areaid, (f, a) => a)
                    .FirstOrDefault();
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            item.Ativo = ativo;
            _context.SaveChanges();
            return Ok();
        }

        [HttpDelete("respostas/{id}")]
        public IActionResult DeleteResposta(int id)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var item = _context.Formularionews.Find(id);
            if (item == null) return NotFound();
            if (!acessoTotal)
            {
                var area = _context.Formularios
                    .Where(f => f.Formularioid == item.Formularioid)
                    .Join(_context.Areas, f => f.Areaid, a => a.Areaid, (f, a) => a)
                    .FirstOrDefault();
                if (area?.Aplicacaoid != claimAppId) return Forbid();
            }
            _context.Formularionews.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSUI.Models;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class GruposController : Controller
    {
        private readonly CmsxDbContext _context;
        public GruposController(CmsxDbContext context) { _context = context; }

        private bool IsAdmin() => User.FindFirstValue("acessoTotal") == "True";

        // Grupos são globais — somente admin gerencia
        [HttpGet]
        public IActionResult Get()
        {
            if (!IsAdmin()) return Forbid();
            return Ok(_context.Grupos.OrderBy(g => g.Nome).ToArray());
        }

        [HttpGet("{id}/usuarios")]
        public IActionResult GetUsuarios(string id)
        {
            if (!IsAdmin()) return Forbid();
            var usuarios = _context.Relusuariogrupos
                .Where(r => r.Grupoid == id)
                .Join(_context.Usuarios, r => r.Usuarioid, u => u.Userid,
                    (r, u) => new { r.Relacaoid, u.Userid, u.Nome, u.Sobrenome, u.Apelido, u.Ativo })
                .ToList();
            return Ok(usuarios);
        }

        public class NovoGrupoDto
        {
            public string Nome { get; set; } = "";
            public string? Descricao { get; set; }
            public bool Acessototal { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] NovoGrupoDto dto)
        {
            if (!IsAdmin()) return Forbid();
            var item = new Grupo
            {
                Grupoid     = Guid.NewGuid().ToString(),
                Nome        = dto.Nome,
                Descricao   = dto.Descricao,
                Acessototal = dto.Acessototal
            };
            _context.Grupos.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] NovoGrupoDto dto)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.Grupos.Find(id);
            if (item == null) return NotFound();
            item.Nome        = dto.Nome;
            item.Descricao   = dto.Descricao;
            item.Acessototal = dto.Acessototal;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.Grupos.Find(id);
            if (item == null) return NotFound();
            var vinculos = _context.Relusuariogrupos.Where(r => r.Grupoid == id).ToList();
            _context.Relusuariogrupos.RemoveRange(vinculos);
            _context.Grupos.Remove(item);
            _context.SaveChanges();
            return Ok();
        }

        [HttpPost("{id}/usuarios")]
        public IActionResult AddUsuario(string id, [FromBody] string usuarioid)
        {
            if (!IsAdmin()) return Forbid();
            if (_context.Relusuariogrupos.Any(r => r.Grupoid == id && r.Usuarioid == usuarioid))
                return BadRequest(new { message = "Usuário já pertence a este grupo." });

            _context.Relusuariogrupos.Add(new Relusuariogrupo
            {
                Relacaoid = Guid.NewGuid().ToString(),
                Grupoid   = id,
                Usuarioid = usuarioid
            });
            _context.SaveChanges();
            return Ok();
        }

        [HttpDelete("{id}/usuarios/{relacaoid}")]
        public IActionResult RemoveUsuario(string id, string relacaoid)
        {
            if (!IsAdmin()) return Forbid();
            var rel = _context.Relusuariogrupos.Find(relacaoid);
            if (rel == null) return NotFound();
            _context.Relusuariogrupos.Remove(rel);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using System.Text.Json;
using CMSUI.Models;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class LayoutTemplatesController : ControllerBase
    {
        private readonly CmsxDbContext _context;
        public LayoutTemplatesController(CmsxDbContext context) => _context = context;

        private bool IsAdmin() => User.FindFirstValue("acessoTotal") == "True";

        [HttpGet]
        public IActionResult Get() =>
            Ok(_context.LayoutTemplates.OrderBy(t => t.Nome).ToList());

        [HttpGet("{id}")]
        public IActionResult Get(string id)
        {
            var t = _context.LayoutTemplates.Find(id);
            return t == null ? NotFound() : Ok(t);
        }

        [HttpGet("padrao")]
        public IActionResult GetPadrao([FromQuery] string tipo = "home")
        {
            var t = _context.LayoutTemplates.FirstOrDefault(x => x.Tipo == tipo && x.Padrao);
            return t == null ? NotFound() : Ok(t);
        }

        public class SalvarTemplateDto
        {
            public string Nome { get; set; } = "";
            public string? Descricao { get; set; }
            public string Tipo { get; set; } = "home";
            public string Layout { get; set; } = "";
            public bool Padrao { get; set; }
        }

        [HttpPost]
        public IActionResult Post([FromBody] SalvarTemplateDto dto)
        {
            if (!IsAdmin()) return Forbid();

            // Se for padrão, remove o padrão anterior do mesmo tipo
            if (dto.Padrao)
                foreach (var t in _context.LayoutTemplates.Where(x => x.Tipo == dto.Tipo && x.Padrao))
                    t.Padrao = false;

            // Valida o JSON do layout
            try { JsonDocument.Parse(dto.Layout); }
            catch { return BadRequest(new { erro = "Layout JSON inválido." }); }

            var item = new LayoutTemplate
            {
                Templateid   = Guid.NewGuid().ToString(),
                Nome         = dto.Nome,
                Descricao    = dto.Descricao,
                Tipo         = dto.Tipo,
                Layout       = dto.Layout,
                Padrao       = dto.Padrao,
                Datainclusao = DateTime.Now
            };
            _context.LayoutTemplates.Add(item);
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpPut("{id}")]
        public IActionResult Put(string id, [FromBody] SalvarTemplateDto dto)
        {
            if (!IsAdmin()) return Forbid();

            var item = _context.LayoutTemplates.Find(id);
            if (item == null) return NotFound();

            if (dto.Padrao)
                foreach (var t in _context.LayoutTemplates.Where(x => x.Tipo == dto.Tipo && x.Padrao && x.Templateid != id))
                    t.Padrao = false;

            item.Nome      = dto.Nome;
            item.Descricao = dto.Descricao;
            item.Tipo      = dto.Tipo;
            item.Layout    = dto.Layout;
            item.Padrao    = dto.Padrao;
            _context.SaveChanges();
            return Ok(item);
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(string id)
        {
            if (!IsAdmin()) return Forbid();
            var item = _context.LayoutTemplates.Find(id);
            if (item == null) return NotFound();
            _context.LayoutTemplates.Remove(item);
            _context.SaveChanges();
            return Ok();
        }
    }
}

using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class MediaController : Controller
    {
        private readonly IConfiguration _config;
        private const long MaxBytes = 5 * 1024 * 1024; // 5 MB
        private static readonly string[] TiposPermitidos =
            ["image/jpeg", "image/png", "image/webp", "image/svg+xml", "image/gif"];

        public MediaController(IConfiguration config) => _config = config;

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        private BlobContainerClient GetContainer()
        {
            var connStr = _config["AzureStorage:ConnectionString"]!;
            var container = _config["AzureStorage:Container"] ?? "cms-imagens";
            return new BlobContainerClient(connStr, container);
        }

        private string ResolverTenant(bool acessoTotal, string? claimAppId, string? queryAppId)
        {
            if (acessoTotal && !string.IsNullOrEmpty(queryAppId)) return queryAppId;
            return claimAppId ?? "global";
        }

        [HttpGet]
        public async Task<IActionResult> Listar([FromQuery] string? aplicacaoid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();
            var tenant = ResolverTenant(acessoTotal, claimAppId, aplicacaoid);
            var prefix = tenant + "/";
            var container = GetContainer();
            var result = new List<object>();
            await foreach (var blob in container.GetBlobsAsync(prefix: prefix))
            {
                result.Add(new
                {
                    nome = blob.Name[prefix.Length..],
                    blobName = blob.Name,
                    url = $"{container.Uri}/{blob.Name}",
                    tamanho = blob.Properties.ContentLength ?? 0,
                    data = blob.Properties.CreatedOn
                });
            }
            return Ok(result);
        }

        [HttpPost("upload")]
        public async Task<IActionResult> Upload([FromQuery] string? aplicacaoid, IFormFile arquivo)
        {
            if (arquivo == null || arquivo.Length == 0)
                return BadRequest(new { erro = "Nenhum arquivo enviado." });
            if (arquivo.Length > MaxBytes)
                return BadRequest(new { erro = "Arquivo muito grande. Limite: 5 MB." });
            if (!TiposPermitidos.Contains(arquivo.ContentType))
                return BadRequest(new { erro = "Tipo não permitido. Use JPG, PNG, WebP, SVG ou GIF." });

            var (acessoTotal, claimAppId) = UserContext();
            var tenant = ResolverTenant(acessoTotal, claimAppId, aplicacaoid);
            var ext = Path.GetExtension(arquivo.FileName);
            var blobName = $"{tenant}/{Guid.NewGuid()}{ext}";

            var container = GetContainer();
            var blob = container.GetBlobClient(blobName);
            var opts = new BlobUploadOptions
            {
                HttpHeaders = new BlobHttpHeaders { ContentType = arquivo.ContentType }
            };
            using var stream = arquivo.OpenReadStream();
            await blob.UploadAsync(stream, opts);

            return Ok(new { url = blob.Uri.ToString(), blobName, nome = Path.GetFileName(blobName) });
        }

        [HttpDelete]
        public async Task<IActionResult> Deletar([FromQuery] string blobName)
        {
            var (acessoTotal, claimAppId) = UserContext();
            if (!acessoTotal && !blobName.StartsWith(claimAppId + "/"))
                return Forbid();
            var container = GetContainer();
            await container.GetBlobClient(blobName).DeleteIfExistsAsync();
            return Ok();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;
using CMSUI.Models;

namespace CMSUI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    [Authorize]
    public class ModulosController : Controller
    {
        private readonly CmsxDbContext _context;
        public ModulosController(CmsxDbContext context) { _context = context; }

        private (bool acessoTotal, string? aplicacaoid) UserContext() =>
            (User.FindFirstValue("acessoTotal") == "True", User.FindFirstValue("aplicacaoid"));

        [HttpGet]
        public IEnumerable<Modulo> Get([FromQuery] string? usuarioid = null)
        {
            var (acessoTotal, claimAppId) = UserContext();

            // Filtro por usuário específico (para montar menu)
            if (!string.IsNullOrEmpty(usuarioid))
                return _context.Relmodulousuarios
                    .Where(r => r.Usuarioid == usuarioid)
                    .Join(_context.Modulos, r => r.Moduloid, m => m.Moduloid, (r, m) => m)
                    .OrderBy(m => m.Posicao)
                    .ToArray();

            // Admin: todos os módulos
            if (acessoTotal)
                return _context.Modulos.OrderBy(m => m.Posicao).ToArray();

            // Tenant: apenas módulos vinculados à sua aplicação
            return _context.Relmoduloaplicacaos
                .Where(r => r.Aplicacaoid == claimAppId)
                .Join(_context.Modulos, r => r.Moduloid, m => m.Moduloid.ToString(), (r, m) => m)
                .OrderBy(m => m.Posicao)
                .ToArray();
        }
    }
}

