import { Component, Inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';

@Component({ templateUrl: './signup.component.html' })
export class SignupComponent {
  dados = {
    nome: '', sobrenome: '', apelido: '', senha: '', confirmarSenha: '',
    appNome: '', appUrl: ''
  };
  erro = '';
  sucesso = '';
  carregando = false;

  constructor(
    private http: HttpClient,
    @Inject('BASE_URL') private baseUrl: string,
    private router: Router
  ) {
    if (sessionStorage.getItem('usuario')) this.router.navigate(['/']);
  }

  cadastrar() {
    this.erro = '';
    if (this.dados.senha !== this.dados.confirmarSenha) {
      this.erro = 'As senhas não conferem.'; return;
    }
    if (!this.dados.apelido || this.dados.apelido.length > 6) {
      this.erro = 'Login deve ter até 6 caracteres.'; return;
    }
    this.carregando = true;
    this.http.post(this.baseUrl + 'auth/signup', this.dados).subscribe({
      next: () => {
        this.sucesso = 'Cadastro realizado! Aguarde a ativação ou faça login.';
        this.carregando = false;
      },
      error: (err) => {
        this.erro = err.error?.message || 'Erro ao realizar cadastro.';
        this.carregando = false;
      }
    });
  }
}

import { Component, Inject, OnInit } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { AdminContextService } from '../admin-context.service';

@Component({ templateUrl: './usuario.component.html' })
export class UsuarioComponent implements OnInit {
  lista: any[] = [];
  selecionado: any = null;
  modoEdicao = false;
  private usuario: any;

  constructor(private http: HttpClient, @Inject('BASE_URL') private baseUrl: string, private adminCtx: AdminContextService) {}

  ngOnInit() {
    this.usuario = JSON.parse(sessionStorage.getItem('usuario') || '{}');
    this.adminCtx.tenant$.subscribe(() => this.carregar());
  }

  private params(): HttpParams {
    let p = new HttpParams();
    if (!this.usuario.acessoTotal && this.usuario.aplicacaoid)
      p = p.set('aplicacaoid', this.usuario.aplicacaoid);
    else if (this.usuario.acessoTotal && this.adminCtx.tenantId)
      p = p.set('aplicacaoid', this.adminCtx.tenantId);
    return p;
  }

  carregar() {
    this.http.get<any[]>(this.baseUrl + 'usuarios', { params: this.params() })
      .subscribe(r => this.lista = r);
  }

  novo() {
    this.selecionado = { nome: '', sobrenome: '', apelido: '', senha: '', ativo: 1 };
    this.modoEdicao = true;
  }

  editar(item: any) {
    this.selecionado = { ...item, senha: '' };
    this.modoEdicao = true;
  }

  salvar() {
    if (this.selecionado.userid) {
      this.http.put(this.baseUrl + 'usuarios/' + this.selecionado.userid, this.selecionado)
        .subscribe(() => { this.modoEdicao = false; this.carregar(); });
    } else {
      this.http.post(this.baseUrl + 'usuarios', this.selecionado)
        .subscribe(() => { this.modoEdicao = false; this.carregar(); });
    }
  }

  excluir(id: string) {
    if (confirm('Excluir usuário?')) {
      this.http.delete(this.baseUrl + 'usuarios/' + id).subscribe(() => this.carregar());
    }
  }

  cancelar() { this.modoEdicao = false; this.selecionado = null; }
}

import { Component, Inject, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({ templateUrl: './vinculo.component.html' })
export class VinculoComponent implements OnInit {
  vinculos: any[] = [];
  usuarios: any[] = [];
  aplicacoes: any[] = [];
  usuarioid = '';
  aplicacaoid = '';
  erro = '';

  constructor(private http: HttpClient, @Inject('BASE_URL') private baseUrl: string) {}

  ngOnInit() {
    this.carregar();
    this.http.get<any[]>(this.baseUrl + 'usuarios').subscribe(r => this.usuarios = r);
    this.http.get<any[]>(this.baseUrl + 'aplicacaos').subscribe(r => this.aplicacoes = r);
  }

  carregar() {
    this.http.get<any[]>(this.baseUrl + 'vinculos').subscribe(r => this.vinculos = r);
  }

  filtrarPorApp(id: string) {
    if (!id) { this.carregar(); return; }
    this.http.get<any[]>(this.baseUrl + 'vinculos?aplicacaoid=' + id)
      .subscribe(r => this.vinculos = r);
  }

  vincular() {
    this.erro = '';
    if (!this.usuarioid || !this.aplicacaoid) {
      this.erro = 'Selecione usuário e aplicação.'; return;
    }
    this.http.post(this.baseUrl + 'vinculos', { usuarioid: this.usuarioid, aplicacaoid: this.aplicacaoid })
      .subscribe({
        next: () => { this.usuarioid = ''; this.aplicacaoid = ''; this.carregar(); },
        error: (err) => this.erro = err.error?.message || 'Erro ao vincular.'
      });
  }

  desvincular(relacaoid: string, nome: string) {
    if (confirm('Remover vínculo de ' + nome + '?')) {
      this.http.delete(this.baseUrl + 'vinculos/' + relacaoid).subscribe(() => this.carregar());
    }
  }
}

