using System;
using System.Collections.Generic;
using System.Text;

namespace Uol.PagSeguro.Domain
{
    /// <summary>
    /// Represents a PagSeguro transaction
    /// </summary>
    public class Transaction
    {
        private IList<Item> items;

        internal Transaction()
        {
        }

        /// <summary>
        /// Transaction date
        /// </summary>
        public DateTime Date
        {
            get;
            internal set;
        }

        /// <summary>
        /// Transaction code
        /// </summary>
        public string Code
        {
            get;
            internal set;
        }

        /// <summary>
        /// Reference code
        /// </summary>
        /// <remarks>
        /// You can use the reference code to store an identifier so you can 
        /// associate the PagSeguro transaction to a transaction in your system.
        /// </remarks>
        public string Reference
        {
            get;
            internal set;
        }

        /// <summary>
        /// Transaction type
        /// </summary>
        public int TransactionType
        {
            get;
            internal set;
        }

        /// <summary>
        /// Transaction status
        /// </summary>
        public int TransactionStatus
        {
            get;
            internal set;
        }

        /// <summary>
        /// Payment method
        /// </summary>
        public PaymentMethod PaymentMethod
        {
            get;
            internal set;
        }

        /// <summary>
        /// Gross amount of the transaction
        /// </summary>
        public decimal GrossAmount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Discount amount
        /// </summary>
        public decimal DiscountAmount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Fee amount
        /// </summary>
        public decimal FeeAmount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Net amount
        /// </summary>
        public decimal NetAmount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Extra amount
        /// </summary>
        public decimal ExtraAmount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Last event date
        /// </summary>
        public DateTime LastEventDate
        {
            get;
            internal set;
        }

        /// <summary>
        /// Installment count
        /// </summary>
        public int InstallmentCount
        {
            get;
            internal set;
        }

        /// <summary>
        /// Payer information
        /// </summary>
        /// <remarks>
        /// Who is sending the money
        /// </remarks>
        public Sender Sender
        {
            get;
            internal set;
        }

        /// <summary>
        /// Products/items in this transaction
        /// </summary>
        public IList<Item> Items
        {
            get
            {
                if (this.items == null)
                {
                    this.items = new List<Item>();
                }
                return items;
            }
        }

        /// <summary>
        /// Shipping information
        /// </summary>
        public Shipping Shipping
        {
            get;
            internal set;
        }

        /// <summary>
        /// Name
        /// </summary>
        /// <remarks>
        /// Name of PreApproval
        /// </remarks>
        public string Name
        {
            get;
            internal set;
        }

        /// <summary>
        /// Tracker
        /// </summary>
        /// <remarks>
        /// Status of PreApproval
        /// </remarks>
        public string Tracker
        {
            get;
            internal set;
        }

        /// <summary>
        /// Status
        /// </summary>
        /// <remarks>
        /// PreApproval Status
        /// </remarks>
        public string Status
        {
            get;
            internal set;
        }

        /// <summary>
        /// charge
        /// </summary>
        /// <remarks>
        /// Manual or Auto
        /// </remarks>
        public string Charge
        {
            get;
            internal set;
        }

        /// <summary>
        /// Returns a string that represents the current object
        /// </summary>
        /// <returns></returns>
        public override string ToString()
        {
            StringBuilder builder = new StringBuilder();
            builder.Append(this.GetType().Name);
            builder.Append('(');
            builder.Append("Code=").Append(this.Code).Append(", ");
            builder.Append("Date=").Append(this.Date).Append(", ");
            builder.Append("Reference=").Append(this.Reference.ToString()).Append(", ");
            builder.Append("TransactionStatus=").Append(this.TransactionStatus).Append(", ");
            string email = this.Sender == null ? null : this.Sender.Email;
            builder.Append("Sender.Email=").Append(email).Append(", ");
            builder.Append("Items.Count=").Append(this.Items.Count);
            builder.Append(')');
            return builder.ToString();
        }
    }
}

