@Injectable()
export class LojaApiService {

  constructor(
    private http: HttpClient,
    @Inject('BASE_URL') private baseUrl: string
  ) {}

  getProdutos(aplicacaoid: string): Observable<Produto[]> {
    const p = new HttpParams().set('aplicacaoid', aplicacaoid);
    return this.http.get<Produto[]>(this.baseUrl + 'api/loja/catalogo', { params: p });
  }

  getClientes(): Observable<ClienteLoja[]> {
    return this.http.get<ClienteLoja[]>(this.baseUrl + 'api/loja/clientes');
  }

  cadastrarCliente(cliente: Omit<ClienteLoja, 'salematicClienteId'>): Observable<ClienteLoja> {
    return this.http.post<ClienteLoja>(this.baseUrl + 'api/loja/clientes', cliente);
  }

  criarPedido(pedido: NovoPedido): Observable<any> {
    return this.http.post(this.baseUrl + 'api/loja/pedidos', pedido);
  }

  getPedidos(params?: { aplicacaoid?: string; status?: string }): Observable<any[]> {
    let p = new HttpParams();
    if (params?.aplicacaoid) p = p.set('aplicacaoid', params.aplicacaoid);
    if (params?.status) p = p.set('status', params.status);
    return this.http.get<any[]>(this.baseUrl + 'api/loja/pedidos', { params: p });
  }

  getMeusPedidos(email: string): Observable<any[]> {
    const p = new HttpParams().set('email', email);
    return this.http.get<any[]>(this.baseUrl + 'api/loja/meus-pedidos', { params: p });
  }

  getTimeline(pedidoid: string): Observable<any[]> {
    return this.http.get<any[]>(`${this.baseUrl}api/loja/pedidos/${pedidoid}/timeline`);
  }

  login(req: LoginRequest): Observable<LojaAuthResponse> {
    return this.http.post<LojaAuthResponse>(this.baseUrl + 'api/loja/auth/login', req);
  }

  registrar(req: RegistrarRequest): Observable<LojaAuthResponse> {
    return this.http.post<LojaAuthResponse>(this.baseUrl + 'api/loja/auth/registrar', req);
  }

  consultarCep(cep: string) {
    return this.http.get(`https://viacep.com.br/ws/${cep.replace(/\D/g, '')}/json/`);
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, map } from 'rxjs';

export interface LojaAuthResponse {
  token: string;
  clienteId: number;
  nome: string;
  email: string;
}

const STORAGE_KEY = 'loja_auth';

@Injectable()
export class LojaAuthService {
  private _auth = new BehaviorSubject<LojaAuthResponse | null>(this.carregar());

  readonly auth$ = this._auth.asObservable();
  readonly isAutenticado$: Observable<boolean> = this._auth.pipe(map(a => !!a));

  get auth(): LojaAuthResponse | null {
    return this._auth.value;
  }

  get isAutenticado(): boolean {
    return !!this._auth.value;
  }

  getToken(): string | null {
    return this._auth.value?.token ?? null;
  }

  salvarAuth(auth: LojaAuthResponse): void {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(auth));
    this._auth.next(auth);
  }

  logout(): void {
    localStorage.removeItem(STORAGE_KEY);
    this._auth.next(null);
  }

  private carregar(): LojaAuthResponse | null {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }
}

import { Injectable, Inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';
import { ActivatedRoute } from '@angular/router';

export interface LojaCtx {
  aplicacaoid: string;
  nomeLoja: string;
  slug: string;
}

@Injectable({ providedIn: 'root' })
export class LojaContextService {
  private _ctx = new BehaviorSubject<LojaCtx | null>(null);
  ctx$ = this._ctx.asObservable();
  private _slug = '';

  constructor(
    private http: HttpClient,
    @Inject('BASE_URL') private baseUrl: string,
    private route: ActivatedRoute
  ) {}

  get aplicacaoid(): string {
    return this._ctx.value?.aplicacaoid ?? this.fromSession();
  }

  get slug(): string {
    return this._ctx.value?.slug ?? this._slug;
  }

  get nomeLoja(): string {
    return this._ctx.value?.nomeLoja ?? 'Loja';
  }

  initFromSlug(slug: string): Observable<LojaCtx> {
    this._slug = slug; // disponível imediatamente, sem depender da API
    return this.http.get<LojaCtx>(`${this.baseUrl}api/loja/resolve?slug=${slug}`).pipe(
      tap(ctx => this._ctx.next({...ctx,slug}))
    );
  }

  initFromSession(): void {
    const usuario = JSON.parse(sessionStorage.getItem('usuario') || '{}');
    const aplicacaoid = usuario.aplicacaoid ?? '';
    if (aplicacaoid) {
      this._ctx.next({
        aplicacaoid, nomeLoja: 'Loja',
        slug: this.slug
      });
    }
  }

  private fromSession(): string {
    const usuario = JSON.parse(sessionStorage.getItem('usuario') || '{}');
    return usuario.aplicacaoid ?? '';
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface TenantCtx { aplicacaoid: string; nome: string; }

@Injectable({ providedIn: 'root' })
export class AdminContextService {
  private _tenant = new BehaviorSubject<TenantCtx | null>(this.loadStored());
  tenant$ = this._tenant.asObservable();

  get tenantId(): string | null { return this._tenant.value?.aplicacaoid ?? null; }

  set(tenant: TenantCtx | null) {
    this._tenant.next(tenant);
    if (tenant) sessionStorage.setItem('adminTenant', JSON.stringify(tenant));
    else sessionStorage.removeItem('adminTenant');
  }

  private loadStored(): TenantCtx | null {
    try { return JSON.parse(sessionStorage.getItem('adminTenant') ?? 'null'); }
    catch { return null; }
  }
}

