interface DictBloco {
  tipobloco: string;
  nome: string;
  descricao: string;
  icone: string;
  schemaConfig: string;
}

interface BlocoLayout {
  tipo: string;
  config: any;
  coluna?: string;
  _nome?: string;
  _icone?: string;
}

@Component({ templateUrl: './page-builder.component.html' })
export class PageBuilderComponent implements OnInit {
  areas: any[] = [];
  blocos: DictBloco[] = [];

  areaid: string = '';
  areaNome: string = '';
  descricao: string = '';
  provedor: string = '';
  gerando = false;
  salvando = false;

  layoutAtual: BlocoLayout[] = [];
  layoutsResumo: { areaid: string; nome: string; qtdBlocos: number }[] = [];
  erro: string = '';
  sucesso: string = '';

  // Galeria de mídias
  galeriaAberta = false;
  galeriaImagens: any[] = [];
  uploadando = false;
  galeriaPickerAberto = false;
  galeriaPickerCampo: string | null = null;

  // Templates
  usuario: any = {};
  isAdmin = false;
  templates: any[] = [];
  tplAberto = false;
  tplNome = '';
  tplDescricao = '';
  tplTipo = 'home';
  tplPadrao = false;
  tplSalvando = false;

  // Paleta de cores
  paletaAberta = false;
  paletaExtraindo = false;
  paletaErro = '';
  paleta: { primaria: string; secundaria: string; fundo: string; texto: string; destaque: string } | null = null;

  extrairPaleta(event: Event) {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) return;
    this.paletaExtraindo = true;
    this.paletaErro = '';
    this.paleta = null;

    const reader = new FileReader();
    reader.onload = () => {
      const base64 = (reader.result as string).split(',')[1];
      this.http.post<any>(`${this.baseUrl}pagebuilder/extrair-paleta`, {
        imagemBase64: base64,
        mimeType: file.type,
        provedor: this.provedor || null
      }).subscribe({
        next: r => {
          this.paletaExtraindo = false;
          try { this.paleta = JSON.parse(r.paleta); }
          catch { this.paletaErro = 'Erro ao processar paleta.'; }
        },
        error: e => {
          this.paletaExtraindo = false;
          const body = e?.error;
          this.paletaErro = body?.detalhe ?? body?.erro ?? 'Erro ao extrair paleta.';
        }
      });
    };
    reader.readAsDataURL(file);
  }

  copiarCor(hex: string) {
    navigator.clipboard.writeText(hex);
  }

  // Configurações de IA
  configAberta = false;
  cfgProvedor = '';
  cfgApikey = '';
  cfgModelo = '';
  cfgLimiteDiario: number | null = null;
  cfgTemChavePropria = false;
