using System.Text.Json;
using System.Text.Json.Nodes;
using Anthropic.SDK;
using Anthropic.SDK.Common;
using Anthropic.SDK.Messaging;
using Salematic.Domain.Interfaces;
using Salematic.Domain.Models;

namespace Salematic.Infrastructure.LLM;

public class AnthropicLlmClient : ILlmClient
{
    private readonly AnthropicClient _client;
    private readonly string _model;

    public AnthropicLlmClient(string apiKey, string model)
    {
        _client = new AnthropicClient(apiKey);
        _model = model;
    }

    public async Task<LlmResponse> EnviarAsync(string systemPrompt, List<LlmMensagem> mensagens, List<LlmFerramenta> ferramentas)
    {
        var response = await _client.Messages.GetClaudeMessageAsync(new MessageParameters
        {
            Model = _model,
            MaxTokens = 1024,
            System = [new SystemMessage(systemPrompt)],
            Messages = TraduzirMensagens(mensagens),
            Tools = TraduzirFerramentas(ferramentas)
        });

        return TraduzirResposta(response);
    }

    public async Task<LlmResponse> EnviarResultadoToolAsync(
        string systemPrompt, List<LlmMensagem> mensagens, List<LlmFerramenta> ferramentas,
        string idChamada, string nomeFerramenta, string resultadoJson)
    {
        var msgs = TraduzirMensagens(mensagens);
        msgs.Add(new Message
        {
            Role = RoleType.User,
            Content = new List<ContentBase>
            {
                new ToolResultContent
                {
                    ToolUseId = idChamada,
                    Content = new List<ContentBase> { new TextContent { Text = resultadoJson } }
                }
            }
        });

        var response = await _client.Messages.GetClaudeMessageAsync(new MessageParameters
        {
            Model = _model,
            MaxTokens = 1024,
            System = [new SystemMessage(systemPrompt)],
            Messages = msgs,
            Tools = TraduzirFerramentas(ferramentas)
        });

        return TraduzirResposta(response);
    }

    private static List<Message> TraduzirMensagens(List<LlmMensagem> mensagens) =>
        mensagens.Select(m => new Message
        {
            Role = m.Role == "user" ? RoleType.User : RoleType.Assistant,
            Content = new List<ContentBase> { new TextContent { Text = m.Content } }
        }).ToList();

    private static IList<Anthropic.SDK.Common.Tool> TraduzirFerramentas(List<LlmFerramenta> ferramentas) =>
        ferramentas.Select(f => (Anthropic.SDK.Common.Tool)new Function(
            f.Nome,
            f.Descricao,
            JsonNode.Parse(JsonSerializer.Serialize(new
            {
                type = "object",
                properties = f.Parametros,
                required = f.Obrigatorios
            }))
        )).ToList();

    private static LlmResponse TraduzirResposta(MessageResponse response)
    {
        if (response.StopReason == "tool_use")
        {
            var toolUse = response.Content.OfType<ToolUseContent>().First();
            return new LlmResponse
            {
                TipoResposta = "tool_use",
                NomeFerramenta = toolUse.Name,
                IdChamada = toolUse.Id,
                Argumentos = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(toolUse.Input.ToJsonString())
            };
        }

        return new LlmResponse
        {
            TipoResposta = "text",
            TextoResposta = response.Content.OfType<TextContent>().First().Text
        };
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using Salematic.Domain.Interfaces;
using Salematic.Domain.Models;

namespace Salematic.Infrastructure.LLM;

public class GeminiLlmClient : ILlmClient
{
    private readonly HttpClient _http;
    private readonly string _apiKey;
    private readonly string _model;
    private const string BaseUrl = "https://generativelanguage.googleapis.com/v1beta";

    public GeminiLlmClient(string apiKey, string model)
    {
        _http = new HttpClient();
        _apiKey = apiKey;
        _model = model;
    }

    public async Task<LlmResponse> EnviarAsync(string systemPrompt, List<LlmMensagem> mensagens, List<LlmFerramenta> ferramentas)
    {
        var payload = new
        {
            system_instruction = new { parts = new[] { new { text = systemPrompt } } },
            contents = FiltrarMensagens(mensagens),
            tools = new[]
            {
                new
                {
                    function_declarations = ferramentas.Select(f => new
                    {
                        name = f.Nome,
                        description = f.Descricao,
                        parameters = f.Parametros
                    })
                }
            },
            generationConfig = new { thinkingConfig = new { thinkingBudget = 0 } }
        };

        var url = $"{BaseUrl}/models/{_model}:generateContent?key={_apiKey}";
        var response = await _http.PostAsJsonAsync(url, payload);
        if (!response.IsSuccessStatusCode)
        {
            var erro = await response.Content.ReadAsStringAsync();
            throw new InvalidOperationException($"Gemini {(int)response.StatusCode}: {erro}");
        }

        var json = await response.Content.ReadAsStringAsync();
        return ParseGeminiResponse(json);
    }

    public async Task<LlmResponse> EnviarResultadoToolAsync(
        string systemPrompt, List<LlmMensagem> mensagens, List<LlmFerramenta> ferramentas,
        string idChamada, string nomeFerramenta, string resultado)
    {
        var contents = FiltrarMensagens(mensagens).Cast<object>().ToList();

        // Gemini exige que response seja um objeto (Struct), nunca array
        // Sempre envolve o resultado em { output: ... }
        var resultadoElement = JsonSerializer.Deserialize<JsonElement>(resultado);
        contents.Add(new
        {
            role = "user",
            parts = new[] { new { function_response = new { name = nomeFerramenta, response = new { output = resultadoElement } } } }
        });

        var payload = new
        {
            system_instruction = new { parts = new[] { new { text = systemPrompt } } },
            contents,
            tools = new[]
            {
                new
                {
                    function_declarations = ferramentas.Select(f => new
                    {
                        name = f.Nome,
                        description = f.Descricao,
                        parameters = f.Parametros
                    })
                }
            },
            generationConfig = new { thinkingConfig = new { thinkingBudget = 0 } }
        };

        var url = $"{BaseUrl}/models/{_model}:generateContent?key={_apiKey}";
        var response = await _http.PostAsJsonAsync(url, payload);
        if (!response.IsSuccessStatusCode)
        {
            var erro = await response.Content.ReadAsStringAsync();
            throw new InvalidOperationException($"Gemini {(int)response.StatusCode}: {erro}");
        }

        var json = await response.Content.ReadAsStringAsync();
        return ParseGeminiResponse(json);
    }

    private static IEnumerable<object> FiltrarMensagens(List<LlmMensagem> mensagens) =>
        mensagens
            .Where(m => !string.IsNullOrWhiteSpace(m.Content))
            .Select(m => new
            {
                role = m.Role == "assistant" ? "model" : "user",
                parts = new[] { new { text = m.Content } }
            });

    private static LlmResponse ParseGeminiResponse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var parts = doc.RootElement
            .GetProperty("candidates")[0]
            .GetProperty("content")
            .GetProperty("parts");

        // Gemini pode retornar texto + functionCall em parts separados — prioriza functionCall
        foreach (var part in parts.EnumerateArray())
        {
            if (part.TryGetProperty("functionCall", out var fc))
            {
                return new LlmResponse
                {
                    TipoResposta = "tool_use",
                    NomeFerramenta = fc.GetProperty("name").GetString(),
                    IdChamada = fc.GetProperty("name").GetString(),
                    Argumentos = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(
                        fc.GetProperty("args").GetRawText())
                };
            }
        }

        // Nenhuma functionCall — retorna texto do primeiro part
        return new LlmResponse
        {
            TipoResposta = "text",
            TextoResposta = parts[0].GetProperty("text").GetString() ?? string.Empty
        };
    }
}

using Microsoft.Extensions.Configuration;
using Salematic.Domain.Interfaces;

namespace Salematic.Infrastructure.LLM;

public static class LlmFactory
{
    public static ILlmClient Create(IConfiguration config)
    {
        var provider = config["Llm:Provider"] ?? "Anthropic";

        return provider.ToLower() switch
        {
            "gemini" => new GeminiLlmClient(
                config["Llm:Gemini:ApiKey"] ?? throw new InvalidOperationException("Llm:Gemini:ApiKey não configurado"),
                config["Llm:Gemini:Model"] ?? "gemini-2.5-flash"),
            _ => new AnthropicLlmClient(
                config["Llm:Anthropic:ApiKey"] ?? throw new InvalidOperationException("Llm:Anthropic:ApiKey não configurado"),
                config["Llm:Anthropic:Model"] ?? "claude-sonnet-4-6")
        };
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using Salematic.Domain.Interfaces;
using Salematic.Domain.Models;

namespace Salematic.Infrastructure.Payment;

public class AsaasPagamentoService : IPagamentoService
{
    private readonly HttpClient _http;
    private readonly string _baseUrl;

    public AsaasPagamentoService(string apiKey, string baseUrl)
    {
        _http = new HttpClient();
        _http.DefaultRequestHeaders.Add("access_token", apiKey);
        _baseUrl = baseUrl.TrimEnd('/');
    }

    public async Task<ResultadoPagamento> ProcessarAsync(SolicitacaoPagamento solicitacao)
    {
        try
        {
            var customerId = await ObterOuCriarClienteAsync(solicitacao);

            var billingType = solicitacao.MetodoPagamento.ToUpper() switch
            {
                "BOLETO" => "BOLETO",
                "CARTAO" or "CREDIT_CARD" => "CREDIT_CARD",
                _ => "PIX"
            };

            var dueDate = DateTime.UtcNow.AddDays(3).ToString("yyyy-MM-dd");

            var payload = new
            {
                customer = customerId,
                billingType,
                value = solicitacao.Valor,
                dueDate,
                description = $"Pedido #{solicitacao.PedidoId} — Salematic"
            };

            var resp = await _http.PostAsJsonAsync($"{_baseUrl}/payments", payload);
            var json = await resp.Content.ReadAsStringAsync();

            if (!resp.IsSuccessStatusCode)
                return new ResultadoPagamento { Aprovado = false, Mensagem = $"Erro ao gerar cobrança: {json}" };

            var doc = JsonDocument.Parse(json).RootElement;
            var pagamentoId = doc.GetProperty("id").GetString()!;
            var invoiceUrl = doc.TryGetProperty("invoiceUrl", out var inv) ? inv.GetString() : null;
            var bankSlipUrl = doc.TryGetProperty("bankSlipUrl", out var bsu) ? bsu.GetString() : null;

            string? pixCopiaCola = null;
            if (billingType == "PIX")
            {
                try
                {
                    var pixJson = await _http.GetStringAsync($"{_baseUrl}/payments/{pagamentoId}/pixQrCode");
                    var pixDoc = JsonDocument.Parse(pixJson).RootElement;
                    pixCopiaCola = pixDoc.TryGetProperty("payload", out var p) ? p.GetString() : null;
                }
                catch { /* QR code pode não estar disponível imediatamente */ }
            }

            return new ResultadoPagamento
            {
                Aprovado = true,
                Mensagem = "Cobrança gerada com sucesso.",
                CodigoTransacao = pagamentoId,
                LinkPagamento = invoiceUrl,
                PixCopiaCola = pixCopiaCola,
                CodigoBarras = bankSlipUrl,
                DataVencimento = dueDate
            };
        }
        catch (Exception ex)
        {
            return new ResultadoPagamento { Aprovado = false, Mensagem = $"Erro interno: {ex.Message}" };
        }
    }

    private async Task<string> ObterOuCriarClienteAsync(SolicitacaoPagamento sol)
    {
        var doc = LimparDocumento(sol.ClienteDocumento);

        var searchResp = await _http.GetStringAsync($"{_baseUrl}/customers?cpfCnpj={Uri.EscapeDataString(doc)}");
        var searchDoc = JsonDocument.Parse(searchResp).RootElement;

        if (searchDoc.TryGetProperty("data", out var data) && data.GetArrayLength() > 0)
            return data[0].GetProperty("id").GetString()!;

        var payload = new
        {
            name = sol.ClienteNome,
            cpfCnpj = doc,
            email = sol.ClienteEmail,
            mobilePhone = sol.ClienteTelefone
        };

        var createResp = await _http.PostAsJsonAsync($"{_baseUrl}/customers", payload);
        var createJson = await createResp.Content.ReadAsStringAsync();
        var createDoc = JsonDocument.Parse(createJson).RootElement;
        return createDoc.GetProperty("id").GetString()!;
    }

    private static string LimparDocumento(string doc) =>
        new string(doc.Where(char.IsDigit).ToArray());
}

